void print(const string &message, const vector<int> &arr) {
    cout << message << endl;
    int size = arr.size();
    for (int i = 0; i < size; i++) {
        cout << arr[i];
        cout << " ";
    }
    cout << endl;
}

void quickSort(vector<int> &arr, int low, int high) {
    if (low >= high) {
        return;
    }

    int partitionIndex = partition(arr, low, high);
    quickSort(arr, low, partitionIndex - 1);
    quickSort(arr, partitionIndex + 1, high);
}

int partition(vector<int> &arr, int low, int high) {
    int pivotElement = arr[low];
    int i = low;
    int j = high;
    while (i < j) {
        while (arr[i] <= pivotElement && i <= high - 1) {
            i++;
        }

        while (arr[j] > pivotElement && j >= low + 1) {
            j--;
        }

        if (i < j) {
            swap(arr[i], arr[j]);
        }
    }
    swap(arr[low], arr[j]);

    return j;
}

#include <iostream>
#include <vector>

using namespace std;

class Solution {
  public:
    /* Brute Force Approach:
       For each element, check all subsequent elements to see
       if any is smaller — if so, the array is not sorted. */
    bool isSorted(vector<int> &arr) {
        int n = arr.size();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (arr[j] < arr[i]) {
                    return false;
                }
            }
        }
        return true;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N²) — nested loop comparing all pairs.
    Space Complexity: O(1) — no extra space used.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (Single Pass):
       Compare each element with its predecessor. If any element
       is smaller than the previous one, the array is not sorted. */
    bool isSorted(vector<int> &arr) {
        int n = arr.size();
        for (int i = 1; i < n; i++) {
            if (arr[i] < arr[i - 1]) {
                return false;
            }
        }
        return true;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass through the array.
    Space Complexity: O(1) — no extra space used.
    */
};

int main() {
    Solution2 solution;

    /* Example 1: sorted array */
    vector<int> arr1 = {1, 2, 3, 4, 5};
    cout << "Input: [1, 2, 3, 4, 5] -> " << (solution.isSorted(arr1) ? "true" : "false") << endl;

    /* Example 2: unsorted array */
    vector<int> arr2 = {5, 4, 6, 7, 8};
    cout << "Input: [5, 4, 6, 7, 8] -> " << (solution.isSorted(arr2) ? "true" : "false") << endl;

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

class Solution {
  public:
    /* Optimal Approach 1 (Sum):
       Compute the expected sum of [0..n] using the formula n*(n+1)/2,
       subtract the actual sum of the array. The difference is the missing number. */
    int missingNumber(const vector<int> &arr) {
        int n = arr.size();
        int expectedSum = n * (n + 1) / 2;
        int actualSum = 0;

        for (int i = 0; i < n; i++) {
            actualSum += arr[i];
        }

        return expectedSum - actualSum;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass to compute the sum.
    Space Complexity: O(1) — only variables used.
    */
};

class Solution2 {
  public:
    /* Optimal Approach 2 (XOR):
       XOR all array elements with all numbers in [0..n].
       Since x ^ x = 0, every number cancels out except the missing one.
       Note: Preferred over Sum when n is large — avoids potential integer overflow. */
    int missingNumber(const vector<int> &arr) {
        int xorArr = 0;
        int xorRange = 0;
        int n = arr.size();

        for (int i = 0; i < n; i++) {
            xorArr ^= arr[i]; // XOR of all array elements
            xorRange ^= i;    // XOR of [0..n-1]
        }
        xorRange ^= n; // include n to complete [0..n]

        return xorArr ^ xorRange;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass through the array.
    Space Complexity: O(1) — only variables used.
    */
};

int main() {
    Solution2 solution;

    /* Example 1 */
    vector<int> arr1 = {0, 2, 3, 1, 4};
    cout << "Input: [0, 2, 3, 1, 4] -> Missing: " << solution.missingNumber(arr1) << endl;

    /* Example 2 */
    vector<int> arr2 = {0, 1, 2, 4, 5, 6};
    cout << "Input: [0, 1, 2, 4, 5, 6] -> Missing: " << solution.missingNumber(arr2) << endl;

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

class Solution {
  public:
    /* Optimized Approach (Two Pointers):
       Use two pointers, one for each array. Compare elements:
       - If equal, add to result and advance both.
       - If arr1[i] < arr2[j], advance i.
       - Otherwise, advance j. */
    vector<int> intersectionArray(const vector<int> &arr1, const vector<int> &arr2) {
        vector<int> result;
        int i = 0; // pointer to arr1
        int j = 0; // pointer to arr2

        while (i < (int)arr1.size() && j < (int)arr2.size()) {
            if (arr1[i] < arr2[j]) {
                i++;
            } else if (arr1[i] > arr2[j]) {
                j++;
            } else {
                /* Equal — present in both, so add to result */
                result.push_back(arr1[i]);
                i++;
                j++;
            }
        }

        return result;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N1 + N2) — each pointer advances at most to the end of its array.
    Space Complexity: O(min(N1, N2)) — result holds at most min(N1, N2) elements.
    */
};

void printArray(const vector<int> &arr) {
    cout << "[";
    for (int i = 0; i < (int)arr.size(); i++) {
        cout << arr[i];
        if (i < (int)arr.size() - 1) {
            cout << ", ";
        }
    }
    cout << "]" << endl;
}

int main() {
    Solution solution;

    /* Example 1 */
    vector<int> arr1 = {3, 4, 6, 7, 9, 9};
    vector<int> arr2 = {1, 5, 7, 8, 9, 9};

    cout << "arr1: ";
    printArray(arr1);
    cout << "arr2: ";
    printArray(arr2);

    vector<int> result1 = solution.intersectionArray(arr1, arr2);
    cout << "Intersection: ";
    printArray(result1);

    /* Example 2 */
    vector<int> arr3 = {1, 2, 3, 4};
    vector<int> arr4 = {2, 4, 6, 8};

    cout << "\narr1: ";
    printArray(arr3);
    cout << "arr2: ";
    printArray(arr4);

    vector<int> result2 = solution.intersectionArray(arr3, arr4);
    cout << "Intersection: ";
    printArray(result2);

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

class Solution {
  public:
    /* Single Pass:
       Initialize largest with the first element, then scan the rest
       and update whenever a bigger value is found. */
    int largestElement(vector<int> &nums) {
        int largest = nums[0];

        for (int i = 1; i < (int)nums.size(); i++) {
            if (nums[i] > largest) {
                largest = nums[i];
            }
        }

        return largest;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass through the array.
    Space Complexity: O(1) — only one variable used.
    */
};

int main() {
    Solution solution;

    /* Example 1 */
    vector<int> nums1 = {3, 3, 6, 1};
    cout << "Input: [3, 3, 6, 1] -> Largest: " << solution.largestElement(nums1) << endl;

    /* Example 2 */
    vector<int> nums2 = {3, 3, 0, 99, -40};
    cout << "Input: [3, 3, 0, 99, -40] -> Largest: " << solution.largestElement(nums2) << endl;

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

class Solution {
  public:
    /* Optimized Approach (Reversal Algorithm):
       1. Reverse the first k elements.
       2. Reverse the remaining n - k elements.
       3. Reverse the entire array.
       This places the first k elements at the end in correct order. */
    void leftRotate(vector<int> &arr, int k) {
        int n = arr.size();
        if (n == 0) {
            return;
        }

        k = k % n; // handle k >= n

        reverse(arr, 0, k - 1); // reverse first k elements
        reverse(arr, k, n - 1); // reverse remaining elements
        reverse(arr, 0, n - 1); // reverse the whole array
    }

    /* Helper: reverse elements in arr from index start to end */
    void reverse(vector<int> &arr, int start, int end) {
        for (int i = start, j = end; i < j; i++, j--) {
            swap(arr[i], arr[j]);
        }
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — each element is swapped at most twice.
    Space Complexity: O(1) — in-place reversal, no extra space.
    */
};

void printArray(const vector<int> &arr) {
    cout << "[";
    for (int i = 0; i < (int)arr.size(); i++) {
        cout << arr[i];
        if (i < (int)arr.size() - 1) {
            cout << ", ";
        }
    }
    cout << "]" << endl;
}

int main() {
    Solution solution;

    /* Example 1: k = 1 */
    vector<int> arr1 = {1, 2, 3, 4, 5};
    cout << "Original: ";
    printArray(arr1);
    solution.leftRotate(arr1, 1);
    cout << "After left rotate by 1: ";
    printArray(arr1);

    /* Example 2: k = 1 */
    vector<int> arr2 = {-1, 0, 3, 6};
    cout << "\nOriginal: ";
    printArray(arr2);
    solution.leftRotate(arr2, 1);
    cout << "After left rotate by 1: ";
    printArray(arr2);

    /* Example 3: k = 2 */
    vector<int> arr3 = {1, 2, 3, 4, 5};
    cout << "\nOriginal: ";
    printArray(arr3);
    solution.leftRotate(arr3, 2);
    cout << "After left rotate by 2: ";
    printArray(arr3);

    return 0;
}

#include <iostream>
#include <map>
#include <vector>

using namespace std;

class Solution {
  public:
    /* Brute Force Approach:
       Try all subarrays — for each starting index i, accumulate sums
       and check if the sum equals k. Track the longest match. */
    int getLongestSubarray(const vector<int> &arr, int k) {
        int n = arr.size();
        int maxLen = 0;

        for (int i = 0; i < n; i++) {
            int currentSum = 0;
            for (int j = i; j < n; j++) {
                currentSum += arr[j];
                if (currentSum == k) {
                    maxLen = max(maxLen, j - i + 1);
                }
            }
        }

        return maxLen;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N²) — nested loops over all subarrays.
    Space Complexity: O(1) — no extra space.
    */
};

class Solution2 {
  public:
    /* Better Approach (Prefix Sum + Hash Map):
       Works for arrays with positives, zeros, AND negatives.
       Store the first occurrence of each prefix sum. If
       (prefixSum - k) exists in the map, a subarray with sum k ends here. */
    int getLongestSubarray(const vector<int> &arr, int k) {
        int n = arr.size();
        map<int, int> prefixSumIndex; // prefix sum → its first occurrence index
        int prefixSum = 0;
        int maxLen = 0;

        for (int i = 0; i < n; i++) {
            prefixSum += arr[i];

            /* Entire prefix from index 0 to i sums to k */
            if (prefixSum == k) {
                maxLen = i + 1;
            }

            /* If (prefixSum - k) was seen before, subarray [that index + 1 .. i] sums to k */
            if (prefixSumIndex.find(prefixSum - k) != prefixSumIndex.end()) {
                maxLen = max(maxLen, i - prefixSumIndex[prefixSum - k]);
            }

            /* Only store the first occurrence to maximize subarray length */
            if (prefixSumIndex.find(prefixSum) == prefixSumIndex.end()) {
                prefixSumIndex[prefixSum] = i;
            }
        }

        return maxLen;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N log N) — map operations are O(log N) per element.
    Space Complexity: O(N) — map stores up to N prefix sums.
    */
};

class Solution3 {
  public:
    /* Optimal Approach (Two Pointers / Sliding Window):
       Works only when array contains non-negative values (positives and zeros).
       Expand the window to the right. If sum exceeds k, shrink from the left. */
    int getLongestSubarray(const vector<int> &arr, int k) {
        int n = arr.size();
        if (n == 0) {
            return 0;
        }

        int left = 0;
        int right = 0;
        int sum = arr[0];
        int maxLen = 0;

        while (right < n) {
            /* Shrink window from left while sum exceeds k */
            while (left <= right && sum > k) {
                sum -= arr[left];
                left++;
            }

            /* Check if current window sums to k */
            if (sum == k) {
                maxLen = max(maxLen, right - left + 1);
            }

            /* Expand window to the right */
            right++;
            if (right < n) {
                sum += arr[right];
            }
        }

        return maxLen;
    }

    /*
    Complexity Analysis

    Time Complexity: O(2N) — each element is added and removed at most once.
    Space Complexity: O(1) — only pointers and variables used.
    */
};

int main() {
    Solution3 solution;

    /* Example 1 */
    vector<int> arr1 = {1, 2, 3, 1, 1, 1};
    int k1 = 3;
    cout << "Input: [1, 2, 3, 1, 1, 1], k = " << k1
         << " -> Longest Subarray Length: " << solution.getLongestSubarray(arr1, k1) << endl;

    /* Example 2 */
    vector<int> arr2 = {2, 0, 0, 3};
    int k2 = 3;
    cout << "Input: [2, 0, 0, 3], k = " << k2
         << " -> Longest Subarray Length: " << solution.getLongestSubarray(arr2, k2) << endl;

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

class Solution {
  public:
    /* Single Pass:
       Track the current streak of 1s. Reset to 0 on a zero.
       Update the maximum whenever the current streak grows. */
    int findMaxConsecutiveOnes(vector<int> &arr) {
        int n = arr.size();
        int maxCount = 0;
        int currentCount = 0;

        for (int i = 0; i < n; i++) {
            if (arr[i] == 1) {
                currentCount++;
                if (currentCount > maxCount) {
                    maxCount = currentCount;
                }
            } else {
                currentCount = 0;
            }
        }

        return maxCount;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass through the array.
    Space Complexity: O(1) — only two variables used.
    */
};

int main() {
    Solution solution;

    /* Example 1 */
    vector<int> arr1 = {1, 1, 0, 0, 1, 1, 1, 0};
    cout << "Input: [1, 1, 0, 0, 1, 1, 1, 0] -> Max Consecutive Ones: " << solution.findMaxConsecutiveOnes(arr1)
         << endl;

    /* Example 2 */
    vector<int> arr2 = {0, 0, 0, 0, 0, 0, 0, 0};
    cout << "Input: [0, 0, 0, 0, 0, 0, 0, 0] -> Max Consecutive Ones: " << solution.findMaxConsecutiveOnes(arr2)
         << endl;

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

class Solution {
  public:
    /* Two-Pointer Approach:
       1. Find the first zero — this is our swap target (zeroIdx).
       2. Scan forward from that position. Every time we find a non-zero,
          swap it with arr[zeroIdx] and advance zeroIdx.
       After the loop, all zeros have been pushed to the end. */
    void moveZerosToEnd(vector<int> &arr) {
        int n = arr.size();
        int zeroIdx = -1;

        /* Find the index of the first zero */
        for (int i = 0; i < n; i++) {
            if (arr[i] == 0) {
                zeroIdx = i;
                break;
            }
        }

        /* No zeros in the array — nothing to do */
        if (zeroIdx == -1) {
            return;
        }

        /* Swap each non-zero element with the current zero position */
        for (int i = zeroIdx + 1; i < n; i++) {
            if (arr[i] != 0) {
                swap(arr[i], arr[zeroIdx]);
                zeroIdx++;
            }
        }
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — at most two passes through the array.
    Space Complexity: O(1) — in-place swaps, no extra space.
    */
};

void printArray(const vector<int> &arr) {
    cout << "[";
    for (int i = 0; i < (int)arr.size(); i++) {
        cout << arr[i];
        if (i < (int)arr.size() - 1) {
            cout << ", ";
        }
    }
    cout << "]" << endl;
}

int main() {
    Solution solution;

    /* Example 1 */
    vector<int> arr1 = {0, 1, 4, 0, 5, 2};
    cout << "Original: ";
    printArray(arr1);
    solution.moveZerosToEnd(arr1);
    cout << "Result:   ";
    printArray(arr1);

    /* Example 2 */
    vector<int> arr2 = {0, 0, 0, 1, 3, -2};
    cout << "\nOriginal: ";
    printArray(arr2);
    solution.moveZerosToEnd(arr2);
    cout << "Result:   ";
    printArray(arr2);

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

class Solution {
  public:
    /* Two-Pointer Approach:
       writeIndex tracks where the next unique element should go.
       readIndex scans forward — whenever it finds a value different
       from arr[writeIndex], advance writeIndex and copy it there. */
    int removeDuplicates(vector<int> &arr) {
        int n = arr.size();
        if (n == 0) {
            return 0;
        }

        int writeIndex = 0;

        for (int readIndex = 1; readIndex < n; readIndex++) {
            if (arr[readIndex] != arr[writeIndex]) {
                writeIndex++;
                arr[writeIndex] = arr[readIndex];
            }
        }

        return writeIndex + 1; // count of unique elements
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass through the array.
    Space Complexity: O(1) — in-place, no extra space.
    */
};

void printArray(const vector<int> &arr, int count) {
    cout << "[";
    for (int i = 0; i < count; i++) {
        cout << arr[i];
        if (i < count - 1) {
            cout << ", ";
        }
    }
    cout << "]" << endl;
}

int main() {
    Solution solution;

    /* Example 1 */
    vector<int> arr1 = {0, 0, 3, 3, 5, 6};
    int k1 = solution.removeDuplicates(arr1);
    cout << "Unique count: " << k1 << ", Result: ";
    printArray(arr1, k1);

    /* Example 2 */
    vector<int> arr2 = {-2, 2, 4, 4, 4, 4, 5, 5};
    int k2 = solution.removeDuplicates(arr2);
    cout << "Unique count: " << k2 << ", Result: ";
    printArray(arr2, k2);

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

class Solution {
  public:
    /* Optimized Approach (Reversal Algorithm):
       1. Reverse the first n - k elements.
       2. Reverse the last k elements.
       3. Reverse the entire array.
       This places the last k elements at the front in correct order. */
    void rightRotate(vector<int> &arr, int k) {
        int n = arr.size();
        if (n == 0) {
            return;
        }

        k = k % n; // handle k >= n

        reverse(arr, 0, n - 1 - k); // reverse first n-k elements
        reverse(arr, n - k, n - 1); // reverse last k elements
        reverse(arr, 0, n - 1);     // reverse the whole array
    }

    /* Helper: reverse elements in arr from index start to end */
    void reverse(vector<int> &arr, int start, int end) {
        for (int i = start, j = end; i < j; i++, j--) {
            swap(arr[i], arr[j]);
        }
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — each element is swapped at most twice.
    Space Complexity: O(1) — in-place reversal, no extra space.
    */
};

void printArray(const vector<int> &arr) {
    cout << "[";
    for (int i = 0; i < (int)arr.size(); i++) {
        cout << arr[i];
        if (i < (int)arr.size() - 1) {
            cout << ", ";
        }
    }
    cout << "]" << endl;
}

int main() {
    Solution solution;

    /* Example 1: k = 1 */
    vector<int> arr1 = {1, 2, 3, 4, 5};
    cout << "Original: ";
    printArray(arr1);
    solution.rightRotate(arr1, 1);
    cout << "After right rotate by 1: ";
