using namespace std;

class Solution {
  public:
    /* Single Pass:
       Track both the largest and second-largest while scanning.
       When a new largest is found, demote the old largest to second.
       When a value is between the two (and not equal to largest), update second. */
    int secondLargestElement(vector<int> &nums) {
        int n = nums.size();
        if (n < 2) {
            return -1; // handle empty arrays and single-element arrays
        }

        int largest = nums[0];
        int secondLargest = INT_MIN;

        for (int i = 1; i < n; i++) {
            if (nums[i] > largest) {
                secondLargest = largest;
                largest = nums[i];
            } else if (nums[i] > secondLargest && nums[i] != largest) {
                secondLargest = nums[i];
            }
        }

        return (secondLargest == INT_MIN) ? -1 : secondLargest;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass through the array.
    Space Complexity: O(1) — only two variables used.
    */
};

int main() {
    Solution solution;

    /* Example 1 */
    vector<int> nums1 = {8, 8, 7, 6, 5};
    cout << "Input: [8, 8, 7, 6, 5] -> Second Largest: " << solution.secondLargestElement(nums1) << endl;

    /* Example 2 */
    vector<int> nums2 = {10, 10, 10, 10, 10};
    cout << "Input: [10, 10, 10, 10, 10] -> Second Largest: " << solution.secondLargestElement(nums2) << endl;

    return 0;
}

