class Solution {
  public:
    /* Better Approach (Frequency Map):
       Count occurrences of each element using a map.
       Return the element with count == 1. */
    int singleNumber(const vector<int> &arr) {
        int n = arr.size();

        map<int, int> freq;
        for (int i = 0; i < n; i++) {
            freq[arr[i]]++;
        }

        for (auto &[key, count] : freq) {
            if (count == 1) {
                return key;
            }
        }

        return -1;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N log N) — map insertion is O(log N) per element.
    Space Complexity: O(N) — map storing up to N/2 + 1 entries.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (XOR):
       XOR all elements together. Since x ^ x = 0, all pairs cancel out,
       leaving only the single number. */
    int singleNumber(const vector<int> &arr) {
        int result = 0;

        for (int i = 0; i < (int)arr.size(); i++) {
            result ^= arr[i];
        }

        return result;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass through the array.
    Space Complexity: O(1) — only one variable used.
    */
};

