#include <iostream>
#include <vector>

using namespace std;

class Solution {
  public:
    /* Two-Pointer Approach:
       Compare elements from both arrays. Push the smaller one (if not
       a duplicate of the last result entry), then advance that pointer.
       When equal, push once and advance both. Drain remaining elements. */
    vector<int> unionArray(const vector<int> &arr1, const vector<int> &arr2) {
        vector<int> result;
        int i = 0;
        int j = 0;
        int n1 = arr1.size();
        int n2 = arr2.size();

        while (i < n1 && j < n2) {
            if (arr1[i] < arr2[j]) {
                if (result.empty() || result.back() != arr1[i]) {
                    result.push_back(arr1[i]);
                }
                i++;
            } else if (arr1[i] > arr2[j]) {
                if (result.empty() || result.back() != arr2[j]) {
                    result.push_back(arr2[j]);
                }
                j++;
            } else {
                /* Equal — push once, advance both */
                if (result.empty() || result.back() != arr1[i]) {
                    result.push_back(arr1[i]);
                }
                i++;
                j++;
            }
        }

        /* Drain remaining elements from arr1 */
        while (i < n1) {
            if (result.back() != arr1[i]) {
                result.push_back(arr1[i]);
            }
            i++;
        }

        /* Drain remaining elements from arr2 */
        while (j < n2) {
            if (result.back() != arr2[j]) {
                result.push_back(arr2[j]);
            }
            j++;
        }

        return result;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N1 + N2) — each pointer advances at most to the end of its array.
    Space Complexity: O(N1 + N2) — result stores the union.
    */
};

void printArray(const vector<int> &arr) {
    cout << "[";
    for (int i = 0; i < (int)arr.size(); i++) {
        cout << arr[i];
        if (i < (int)arr.size() - 1) {
            cout << ", ";
        }
    }
    cout << "]" << endl;
}

int main() {
    Solution solution;

    /* Example 1 */
    vector<int> arr1 = {1, 2, 3, 4, 5};
    vector<int> arr2 = {1, 2, 7};

    cout << "arr1: ";
    printArray(arr1);
    cout << "arr2: ";
    printArray(arr2);

    vector<int> result1 = solution.unionArray(arr1, arr2);
    cout << "Union: ";
    printArray(result1);

    /* Example 2 */
    vector<int> arr3 = {3, 4, 6, 7, 9, 9};
    vector<int> arr4 = {1, 5, 7, 8, 8};

    cout << "\narr1: ";
    printArray(arr3);
    cout << "arr2: ";
    printArray(arr4);

    vector<int> result2 = solution.unionArray(arr3, arr4);
    cout << "Union: ";
    printArray(result2);

    return 0;
}

