class Solution {
  public:
    /* Brute Force Approach:
       Try every pair (buy day i, sell day j where j > i).
       Track the maximum difference arr[j] - arr[i]. */
    int maxProfit(const vector<int> &prices) {
        int n = prices.size();
        int maxProfit = 0;

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (prices[j] > prices[i]) {
                    maxProfit = max(prices[j] - prices[i], maxProfit);
                }
            }
        }

        return maxProfit;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N²) — check every buy/sell pair.
    Space Complexity: O(1) — no extra space.
    */
};

class Solution2 {
  public:
    /* Optimal Approach:
       Track the minimum price seen so far while scanning left to right.
       At each day, the best profit is current price minus the minimum
       price seen before it. */
    int maxProfit(const vector<int> &prices) {
        int n = prices.size();
        if (n == 0) {
            return 0;
        }

        int minPrice = prices[0];
        int maxProfit = 0;

        for (int i = 1; i < n; i++) {
            /* Profit if we sell today at prices[i] */
            int sellingProfit = prices[i] - minPrice;
            maxProfit = max(sellingProfit, maxProfit);

            /* Update the cheapest buying price seen so far */
            minPrice = min(prices[i], minPrice);
        }

        return maxProfit;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass through the array.
    Space Complexity: O(1) — only variables used.
    */
};

int main() {
    Solution2 solution;

    /* Example 1 */
    vector<int> prices1 = {10, 7, 5, 8, 11, 9};
    cout << "Input: [10, 7, 5, 8, 11, 9] -> Max Profit: " << solution.maxProfit(prices1) << endl;

    /* Example 2 */
    vector<int> prices2 = {5, 4, 3, 2, 1};
    cout << "Input: [5, 4, 3, 2, 1] -> Max Profit: " << solution.maxProfit(prices2) << endl;

    return 0;
}

