using namespace std;

class Solution {
  public:
    /* Brute Force Approach:
       For every element, count how many times it appears in the
       entire array. Return it if the count exceeds n/2. */
    int majorityElement(const vector<int> &nums) {
        int n = nums.size();

        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = 0; j < n; j++) {
                if (nums[j] == nums[i]) {
                    count++;
                }
            }
            if (count > n / 2) {
                return nums[i];
            }
        }

        return -1;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N²) — nested loop counts each element.
    Space Complexity: O(1) — no extra space.
    */
};

class Solution2 {
  public:
    /* Better Approach (Hashing):
       Store frequency of each element in a map, then check which
       element exceeds n/2 occurrences. */
    int majorityElement(const vector<int> &nums) {
        int n = nums.size();
        map<int, int> freqMap;

        for (int i = 0; i < n; i++) {
            freqMap[nums[i]]++;
        }

        for (auto &[value, freq] : freqMap) {
            if (freq > n / 2) {
                return value;
            }
        }

        return -1;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N log N) — map insertion is O(log N) per element.
    Space Complexity: O(N) — map stores up to N distinct elements.
    */
};

class Solution3 {
  public:
    /* Optimal Approach (Boyer-Moore Majority Vote):
       Maintain a candidate and a counter. When the counter drops to 0,
       pick the current element as the new candidate. Equal elements
       increment the counter; different elements decrement it. The true
       majority element always survives because its count exceeds all
       others combined. A verification pass confirms the result. */
    int majorityElement(const vector<int> &nums) {
        int n = nums.size();
        int candidate = 0;
        int count = 0;

        /* Phase 1 — find the candidate */
        for (int i = 0; i < n; i++) {
            if (count == 0) {
                candidate = nums[i];
                count = 1;
            } else if (nums[i] == candidate) {
                count++;
            } else {
                count--;
            }
        }

        /* Phase 2 — verify the candidate is truly the majority */
        int freq = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] == candidate) {
                freq++;
            }
        }

        if (freq > n / 2) {
            return candidate;
        }

        return -1;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — two linear passes.
    Space Complexity: O(1) — only variables used.
    */
};

