    Solution3 solution;

    /* Example 1 */
    vector<int> nums1 = {7, 0, 0, 1, 7, 7, 2, 7, 7};
    cout << "Input: [7, 0, 0, 1, 7, 7, 2, 7, 7] -> Majority Element: " << solution.majorityElement(nums1) << endl;

    /* Example 2 */
    vector<int> nums2 = {1, 1, 1, 2, 1, 2};
    cout << "Input: [1, 1, 1, 2, 1, 2] -> Majority Element: " << solution.majorityElement(nums2) << endl;

    return 0;
}

