class Solution {
  public:
    /* Brute Force Approach:
       Try all subarrays — for each starting index i, accumulate the
       sum up to every ending index j and track the maximum. */
    int maxSubarraySum(const vector<int> &nums) {
        int n = nums.size();
        int maxSum = INT_MIN;

        for (int i = 0; i < n; i++) {
            int currentSum = 0;
            for (int j = i; j < n; j++) {
                currentSum += nums[j];
                maxSum = max(currentSum, maxSum);
            }
        }

        return maxSum;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N²) — two nested loops over all subarrays.
    Space Complexity: O(1) — no extra space.
    */
};

class Solution2 {
  public:
    /* Optimal Approach (Kadane's Algorithm):
       Scan left to right maintaining a running sum. If the running sum
       drops below 0, reset it — a negative prefix can never improve
       a future subarray. Also tracks the subarray boundaries. */
    int maxSubarraySum(const vector<int> &nums) {
        int n = nums.size();
        int currentSum = 0;
        int maxSum = INT_MIN;

        int startIdx = 0;
        int endIdx = 0;
        int tempStart = 0; // candidate start for current window

        for (int i = 0; i < n; i++) {
            /* When sum was reset, this element starts a new candidate subarray */
            if (currentSum <= 0) {
                tempStart = i;
            }

            currentSum += nums[i];

            /* Update best answer and record the subarray boundaries */
            if (currentSum > maxSum) {
                maxSum = currentSum;
                startIdx = tempStart;
                endIdx = i;
            }

            /* Discard negative prefix — it can only hurt future subarrays */
            if (currentSum < 0) {
                currentSum = 0;
            }
        }

        /* Print the subarray that produced the maximum sum */
        cout << "Max subarray: [";
        for (int i = startIdx; i <= endIdx; i++) {
            cout << nums[i];
            if (i < endIdx) {
                cout << ", ";
            }
        }
        cout << "]" << endl;

        return maxSum;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass through the array.
    Space Complexity: O(1) — only variables used.
    */
};

int main() {
    Solution2 solution;

    /* Example 1 */
    vector<int> nums1 = {2, 3, 5, -2, 7, -4};
    cout << "Input: [2, 3, 5, -2, 7, -4] -> Max Sum: " << solution.maxSubarraySum(nums1) << endl;

    /* Example 2 */
    vector<int> nums2 = {-2, -3, -7, -2, -10, -4};
    cout << "Input: [-2, -3, -7, -2, -10, -4] -> Max Sum: " << solution.maxSubarraySum(nums2) << endl;

    /* Example 3 */
    vector<int> nums3 = {-4, -3, -2, -1, 0};
    cout << "Input: [-4, -3, -2, -1, 0] -> Max Sum: " << solution.maxSubarraySum(nums3) << endl;

    return 0;
}

