class Solution {
  public:
    /* Optimal Approach:
       1. Scan from right to find the first index (breakpoint) where
          nums[i] < nums[i+1] — everything to its right is descending.
       2. If no such index exists, the array is the last permutation —
          reverse the whole array to get the first.
       3. Swap nums[breakpoint] with the smallest element to its right
          that is still greater than it.
       4. Reverse the suffix after breakpoint to get the smallest
          possible tail. */
    void nextPermutation(vector<int> &nums) {
        int n = nums.size();

        /* Step 1 — find the breakpoint */
        int breakpoint = -1;
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] < nums[i + 1]) {
                breakpoint = i;
                break;
            }
        }

        /* Step 2 — last permutation → wrap to first */
        if (breakpoint == -1) {
            reverse(nums.begin(), nums.end());
            return;
        }

        /* Step 3 — swap with next-larger element from the right */
        for (int i = n - 1; i > breakpoint; i--) {
            if (nums[i] > nums[breakpoint]) {
                swap(nums[i], nums[breakpoint]);
                break;
            }
        }

        /* Step 4 — reverse the descending suffix to ascending */
        reverse(nums.begin() + breakpoint + 1, nums.end());
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — three linear scans at most.
    Space Complexity: O(1) — in-place rearrangement.
    */
};

int main() {
    Solution solution;

