class Solution {
  public:
    /* Brute Force Approach:
       Separate positives and negatives into two lists, then
       interleave them — positives at even indices, negatives at odd. */
    vector<int> rearrangeArray(vector<int> &nums) {
        int n = nums.size();
        vector<int> positives;
        vector<int> negatives;

        /* Segregate into positives and negatives */
        for (int i = 0; i < n; i++) {
            if (nums[i] >= 0) {
                positives.push_back(nums[i]);
            } else {
                negatives.push_back(nums[i]);
            }
        }

        /* Place positives at even indices, negatives at odd */
        for (int i = 0; i < n / 2; i++) {
            nums[2 * i] = positives[i];
            nums[2 * i + 1] = negatives[i];
        }

        return nums;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — one pass to segregate, another to interleave.
    Space Complexity: O(N) — two auxiliary lists of size N/2 each.
    */
};

class Solution2 {
