       element directly into the result array in a single pass. */
    vector<int> rearrangeArray(vector<int> &nums) {
        int n = nums.size();
        int posIdx = 0; // next even index for positives
        int negIdx = 1; // next odd index for negatives

        vector<int> result(n);

        for (int i = 0; i < n; i++) {
            if (nums[i] >= 0) {
                result[posIdx] = nums[i];
                posIdx += 2;
            } else {
                result[negIdx] = nums[i];
                negIdx += 2;
            }
        }

        return result;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass through the array.
    Space Complexity: O(N) — result array of size N.
    */
};

