class Solution {
  public:
    /* Approach:
       Separate positives and negatives, then interleave up to the
       count of the minority group. Append the leftover elements
       from the majority group at the end. */
    vector<int> rearrangeArray(vector<int> &nums) {
        int n = nums.size();
        vector<int> positives;
        vector<int> negatives;

        /* Segregate into positives and negatives */
        for (int i = 0; i < n; i++) {
            if (nums[i] >= 0) {
                positives.push_back(nums[i]);
            } else {
                negatives.push_back(nums[i]);
            }
        }

        int numPos = positives.size();
        int numNeg = negatives.size();
        int minCount = min(numPos, numNeg);

        /* Interleave up to the smaller count */
        for (int i = 0; i < minCount; i++) {
            nums[2 * i] = positives[i];
            nums[2 * i + 1] = negatives[i];
        }

        /* Append leftover elements from the larger group */
        int idx = minCount * 2;
        if (numPos > numNeg) {
            for (int i = minCount; i < numPos; i++) {
                nums[idx++] = positives[i];
            }
        } else {
            for (int i = minCount; i < numNeg; i++) {
                nums[idx++] = negatives[i];
            }
        }

        return nums;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — one pass to segregate, one to interleave and append.
    Space Complexity: O(N) — two auxiliary lists storing all elements.
    */
};

