class Solution {
  public:
    /* Better Approach (Counting):
       Count the frequency of 0s, 1s, and 2s, then overwrite the
       array in order. Two passes — one to count, one to fill. */
    void sortZeroOneTwo(vector<int> &nums) {
        int n = nums.size();
        int count0 = 0, count1 = 0, count2 = 0;

        for (int i = 0; i < n; i++) {
            if (nums[i] == 0) {
                count0++;
            } else if (nums[i] == 1) {
                count1++;
            } else {
                count2++;
            }
        }

        /* Overwrite in sorted order */
        int idx = 0;
        while (idx < n) {
            if (idx < count0) {
                nums[idx] = 0;
            } else if (idx < count0 + count1) {
                nums[idx] = 1;
            } else {
                nums[idx] = 2;
            }
            idx++;
        }
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — two linear passes.
    Space Complexity: O(1) — only counters used.
    */
};

class Solution2 {
  public:
    /* Optimal Approach (Dutch National Flag Algorithm):
       Three pointers — low, mid, high — partition the array into:
         [0..low-1] = 0s, [low..mid-1] = 1s, [high+1..n-1] = 2s.
       The segment [mid..high] is unsorted.
       - nums[mid] == 0: swap with low, advance both.
       - nums[mid] == 1: advance mid.
       - nums[mid] == 2: swap with high, decrement high (re-check mid). */
    void sortZeroOneTwo(vector<int> &nums) {
        int n = nums.size();
        int low = 0;
        int mid = 0;
        int high = n - 1;

        while (mid <= high) {
            if (nums[mid] == 0) {
                swap(nums[low], nums[mid]);
                low++;
                mid++;
            } else if (nums[mid] == 1) {
                mid++;
            } else {
                swap(nums[mid], nums[high]);
                high--;
            }
        }
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass through the array.
    Space Complexity: O(1) — in-place with three pointers.
    */
};

int main() {
    Solution2 solution;

    /* Example 1 */
    vector<int> nums1 = {1, 0, 2, 1, 0};
    cout << "Input: [1, 0, 2, 1, 0] -> Sorted: ";
    solution.sortZeroOneTwo(nums1);
    printArray(nums1);
    cout << endl;

    /* Example 2 */
    vector<int> nums2 = {0, 0, 1, 1, 1};
    cout << "Input: [0, 0, 1, 1, 1] -> Sorted: ";
    solution.sortZeroOneTwo(nums2);
    printArray(nums2);
    cout << endl;

    return 0;
}

