class Solution {
  public:
    /* Brute Force Approach:
       Try every pair (i, j). If their values sum to the target,
       return the pair of indices. */
    vector<int> twoSum(const vector<int> &nums, int target) {
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (nums[i] + nums[j] == target) {
                    return {i, j};
                }
            }
        }
        return {};
    }

    /*
    Complexity Analysis

    Time Complexity: O(N²) — check every pair.
    Space Complexity: O(1) — no extra space.
    */
};

class Solution2 {
  public:
    /* Optimal Approach (Hash Map):
       For each element, check if (target - current) was already seen.
       If so, return both indices. Otherwise, store the current element
       and its index in the map. */
    vector<int> twoSum(const vector<int> &nums, int target) {
        unordered_map<int, int> seen; // value → index
        int n = nums.size();

        for (int i = 0; i < n; i++) {
            int complement = target - nums[i];
            if (seen.find(complement) != seen.end()) {
                return {seen[complement], i};
            }
            seen[nums[i]] = i;
        }

        return {};
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass with O(1) average map lookups.
    Space Complexity: O(N) — map stores up to N elements.
    */
};

