    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *next) : data(x), next(next) {}
};

class Solution {
  public:
    ListNode *addTwoNumbers(ListNode *&linkedList1, ListNode *&linkedList2) {
        ListNode *dummyHead = new ListNode();
        ListNode *current = dummyHead;
        int carry = 0;

        while (linkedList1 != nullptr || linkedList2 != nullptr || carry) {
            int sum = carry;

            if (linkedList1 != nullptr) {
                sum += linkedList1->data;
                linkedList1 = linkedList1->next;
            }

            if (linkedList2 != nullptr) {
                sum += linkedList2->data;
                linkedList2 = linkedList2->next;
            }

            carry = sum / 10;
            current->next = new ListNode(sum % 10);
            current = current->next;
        }

        return dummyHead->next;
    }

    /*
    Complexity Analysis:
    Time Complexity: O(max(M, N)) Here, M and N represent the sizes of the linked lists l1 and l2, respectively. The
    algorithm traverses both lists at most once, hence, the time complexity depends on the length of the longer list.

    Space Complexity: O(max(M,N)) The length of the new list is at most max(M, N)+1.
    */
};

void printList(ListNode *head) {
    ListNode *current = head;
    while (current != nullptr) {
        cout << current->data;
        if (current->next != nullptr)
            cout << " -> ";
        current = current->next;
    }
    cout << endl;
}

void freeList(ListNode *head) {
    while (head != nullptr) {
        ListNode *temp = head;
        head = head->next;
        delete temp;
    }
}

