class Solution {
  public:
    /* Given a node (guaranteed not to be the head), remove it from the DLL.
       Link its previous and next neighbours to each other, then free it. */
    void deleteGivenNode(ListNode *node) {
        ListNode *prevNode = node->prev;
        ListNode *nextNode = node->next;

        /* Link previous node to the next node (works even if nextNode is
           nullptr, i.e. the node is the tail) */
        prevNode->next = nextNode;

        /* If not the tail, link next node back to the previous */
        if (nextNode != nullptr) {
            nextNode->prev = prevNode;
        }

        delete node;
    }

    /*
    Complexity Analysis

    Time Complexity: O(1) — direct pointer rewiring with no traversal.
    Space Complexity: O(1) — only pointers used.
    */
};

