class Solution {
  public:
    ListNode *deleteKthElement(ListNode *&head, int k) {
        if (head == nullptr || head->next == nullptr) {
            if (k == 1) {
                delete head;
            }

            return nullptr;
        }

        // First Node
        if (k == 1) {
            ListNode *temp = head;
            head = head->next;

            temp->next = nullptr;
            head->prev = nullptr;

            delete temp;

            return head;
        }

        ListNode *current = head;
        int counter{0};

        while (current->next != nullptr) {
            counter++;

            if (counter == k) {
                current->prev->next = current->next;
                current->next->prev = current->prev;

                current->prev = nullptr;
                current->next = nullptr;

                delete current;

                return head;
            }

            current = current->next;
        }

        // Last Node
        if (counter + 1 == k) {
            current->prev->next = nullptr;
            current->prev = nullptr;

            delete current;

            return head;
        }

        // If K > len(linked list)
        return head;
    }
};

