#include <iostream>
#include <vector>

using namespace std;

class ListNode {
  public:
    int data;
    ListNode *next;

    ListNode() : data(0), next(nullptr) {}

    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /* Brute Force Approach (Two-Pass):
       First pass counts the total length of the list.
       Second pass walks to the node just before the target and removes it. */
    ListNode *removeNthFromEnd(ListNode *head, int n) {
        /* Empty list — nothing to remove */
        if (head == nullptr) {
            return head;
        }

        ListNode *current = head;
        int length{0};

        /* Step 1: Calculate the total length of the list */
        while (current != nullptr) {
            length++;
            current = current->next;
        }

        /* Special case: if n equals the length, the head itself
           is the node to delete — just move head forward. */
        if (length == n) {
            current = head;
            head = head->next;
            delete current;
            return head;
        }

        /* Step 2: The node to delete is at position (length - n + 1) from front.
           We need to stop at the node just before it, i.e. position (length - n). */
        int del_ind = length - n;

        current = head;
        int curr_ind{1};
        while (current != nullptr) {
            if (curr_ind == del_ind) {
                break;
            }
            curr_ind++;
            current = current->next;
        }

        /* Step 3: Unlink the target node and free its memory */
        ListNode *deleteNode = current->next;
        current->next = current->next->next;

        delete deleteNode;

        return head;
    }

    /*
    Complexity Analysis

    Time Complexity: O(2N) — one pass to find length, one pass to reach the target node.
    Space Complexity: O(1) — only a few pointers and counters used.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (Single-Pass with Two Pointers):
       Move fast_ptr n steps ahead of slow_ptr so they maintain a gap of n.
       When fast_ptr reaches the last node, slow_ptr is right before the
       node to delete. No need to compute the list length first. */
    ListNode *removeNthFromEnd(ListNode *head, int n) {
        /* Empty list — nothing to remove */
        if (head == nullptr) {
            return head;
        }

        ListNode *fast_ptr = head;
        ListNode *slow_ptr = head;

        /* Step 1: Advance fast_ptr by n positions to create the gap.
           After this, fast_ptr is n nodes ahead of slow_ptr. */
        for (int i = 0; i < n; i++) {
            fast_ptr = fast_ptr->next;
        }

        /* Special case: if fast_ptr is nullptr after n steps,
           the node to remove is the head itself. */
        if (fast_ptr == nullptr) {
            ListNode *delNode = head;
            head = head->next;

            delete delNode;

            return head;
        }

        /* Step 2: Move both pointers one step at a time until fast_ptr
           hits the last node. Now slow_ptr is just before the target. */
        while (fast_ptr->next != nullptr) {
            fast_ptr = fast_ptr->next;
            slow_ptr = slow_ptr->next;
        }

        /* Step 3: Unlink the target node and free its memory */
        ListNode *delNode = slow_ptr->next;

        slow_ptr->next = slow_ptr->next->next;

        delete delNode;

        return head;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single traversal of the list.
    Space Complexity: O(1) — only two pointers used.
    */
};

/* Helper: build a linked list from a vector of values */
ListNode *buildList(const vector<int> &values) {
    if (values.empty()) {
        return nullptr;
    }

    ListNode *head = new ListNode(values[0]);
    ListNode *tail = head;

    for (int i = 1; i < (int)values.size(); i++) {
        tail->next = new ListNode(values[i]);
        tail = tail->next;
    }

    return head;
}

