class Solution {
  public:
    ListNode *insertAtKthPosition(ListNode *&head, int X, int K) {
        if (head == nullptr) {
            if (K == 1) {
                return new ListNode(X, nullptr);
            }
            return nullptr;
        }

        if (K == 1) {
            return new ListNode(X, head);
        }

        int counter{0};
        ListNode *current = head;
        ListNode *prevCurrent = nullptr;
        while (current != nullptr) {
            counter++;
            if (counter == K) {
                ListNode *newNode = new ListNode(X, current);
                prevCurrent->next = newNode;
                return head;
            }
            prevCurrent = current;
            current = current->next;
        }

        // Insert at the end if K == length + 1
        if (counter + 1 == K) {
            prevCurrent->next = new ListNode(X, nullptr);
        }

        return head;
    }
};

