#include <iostream>
#include <vector>

using namespace std;

class ListNode {
  public:
    int data;
    ListNode *next;

    ListNode() : data(0), next(nullptr) {}

    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /*
    Brute Force Approach:
    Collect odd-indexed values first, then even-indexed values into
    an auxiliary array. Overwrite the original list with this ordering.
    */
    ListNode *oddEvenList(ListNode *&head) {
        /* Nothing to rearrange for 0 or 1 node */
        if (head == nullptr || head->next == nullptr) {
            return head;
        }

        vector<int> arr;

        /* Step 1: Gather all odd-indexed node values (indices 1, 3, 5, …)
           Start at head (index 1) and skip every other node. */
        ListNode *current = head;

        while (current != nullptr && current->next != nullptr) {
            arr.push_back(current->data);
            current = current->next->next; // jump two steps to next odd index
        }

        /* If the list has an odd number of nodes, the last odd-indexed
           node won't be captured inside the loop — pick it up here. */
        if (current != nullptr) {
            arr.push_back(current->data);
        }

        /* Step 2: Gather all even-indexed node values (indices 2, 4, 6, …)
           Start at head->next (index 2) and skip every other node. */
        current = head->next;

        while (current != nullptr && current->next != nullptr) {
            arr.push_back(current->data);
            current = current->next->next; // jump two steps to next even index
        }

        /* Same edge-case: capture the last even-indexed node if it exists. */
        if (current != nullptr) {
            arr.push_back(current->data);
        }

        /* Step 3: Overwrite the original list with the reordered values.
           arr now holds [odd1, odd3, …, even2, even4, …]. */
        current = head;
        int i = 0;

        while (current != nullptr) {
            current->data = arr[i++];
            current = current->next;
        }

        return head;
    }

    /*
    Complexity Analysis

    Time Complexity: O(2xN) for the following reasons:-
    - Traversing the odd-indexed elements takes O(N/2) time.
    - Traversing the even-indexed elements takes O(N/2) time.
    - Updating the linked list with the values from the array takes O(N) time. Here N is the size of the linked list.

    Space Complexity: O(N) because an additional list is used to store the grouped elements from the linked list.
    */
};

class Solution2 {
  public:
    /* Optimized Approach:
       Rearrange nodes in-place by maintaining two separate chains
       (odd-indexed and even-indexed) and stitching them together at the end.
       No extra array is needed — only pointer rewiring. */
    ListNode *oddEvenList(ListNode *&head) {
        /* Nothing to rearrange for 0 or 1 node */
        if (head == nullptr || head->next == nullptr) {
            return head;
        }

        ListNode *odd = head;             // points to the current odd-indexed node
        ListNode *even = head->next;      // points to the current even-indexed node
        ListNode *evenFirst = head->next; // save head of even chain to link later

        /* Walk the list, unlinking odd nodes from even nodes:
           - even != nullptr        → ensures odd->next->next is safe
           - even->next != nullptr  → ensures even->next->next is safe
           Each iteration moves both pointers two positions forward. */
        while (even != nullptr && even->next != nullptr) {
            odd->next = odd->next->next;   // link current odd to the next odd node
            even->next = even->next->next; // link current even to the next even node

            odd = odd->next;   // advance odd pointer
            even = even->next; // advance even pointer
        }

        /* Stitch the two chains: attach even chain right after the last odd node.
           e.g. odd chain: 1 -> 3 -> 5 , even chain: 2 -> 4
           result:         1 -> 3 -> 5 -> 2 -> 4 */
        odd->next = evenFirst;

        return head;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N/2)x2 ~> O(N) because we are iterating over the odd-indexed as well as the even-indexed
    elements. Here N is the size of the given linked list.

    Space Complexity: O(1) because we have not used any extra space.
    */
};

ListNode *buildList(const vector<int> &values) {
    if (values.empty()) {
        return nullptr;
    }

    ListNode *head = new ListNode(values[0]);
    ListNode *tail = head;

    for (int i = 1; i < values.size(); i++) {
        tail->next = new ListNode(values[i]);
        tail = tail->next;
    }

    return head;
}

void printList(ListNode *head) {
    ListNode *current = head;
    while (current != nullptr) {
        cout << current->data;
        if (current->next != nullptr) {
            cout << " -> ";
        }
        current = current->next;
    }
    cout << endl;
}

void deleteList(ListNode *&head) {
    while (head != nullptr) {
        ListNode *temp = head;
        head = head->next;
        delete temp;
    }
}

int main() {
    vector<int> input = {1, 2, 3, 4, 5};

    ListNode *head = buildList(input);

    cout << "Original list: ";
    printList(head);

    Solution2 solution2;
    head = solution2.oddEvenList(head);

    cout << "Rearranged list: ";
    printList(head);

    deleteList(head);

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

class ListNode {
  public:
    int data;
    ListNode *next;

    ListNode() : data(0), next(nullptr) {}

    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /* Iterative Approach (Three Pointers):
       Walk through the list, reversing each node's next pointer
       to point to the previous node instead of the next one.
       prev trails behind, current is the node being processed,
       and front saves the next node before we overwrite the link. */
    ListNode *reverseList(ListNode *head) {
        /* 0 or 1 node — already reversed */
        if (head == nullptr || head->next == nullptr) {
            return head;
        }

        ListNode *current = head;  // node we're currently reversing
        ListNode *prev = nullptr;  // the already-reversed portion (starts empty)
        ListNode *front = nullptr; // saves current->next before we break the link

        while (current != nullptr) {
            front = current->next; // Step 1: save the next node
            current->next = prev;  // Step 2: reverse the link
            prev = current;        // Step 3: advance prev
            current = front;       // Step 4: advance current
        }

        /* prev now points to the last node visited — the new head */
        return prev;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass through the list.
    Space Complexity: O(1) — only three pointers used.
    */
};

class Solution2 {
  public:
    /* Recursive Approach:
       Recurse all the way to the last node — that becomes the new head.
       On each return (unwinding), reverse the link between the current
       node and its next node, then disconnect the forward link. */
    ListNode *reverseList(ListNode *head) {
        /* Base case: 0 or 1 node — already reversed.
           Also acts as the recursion terminator. */
        if (head == nullptr || head->next == nullptr) {
            return head;
        }

        /* Recurse deeper — newHead will always be the original tail node,
           bubbled up through every return. */
        ListNode *newHead = reverseList(head->next);

        /* At this point head->next has already been reversed from here onward.
           Now make head->next point back to head to reverse this link. */
        ListNode *front = head->next;
        front->next = head;

        /* Disconnect head's forward link to avoid a cycle.
           (If head ends up as the final tail, this nullptr stays.) */
        head->next = nullptr;

        return newHead;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — one recursive call per node.
    Space Complexity: O(N) — recursion stack depth equals the list length.
    */
};

/* Helper: build a linked list from a vector of values */
ListNode *buildList(const vector<int> &values) {
    if (values.empty()) {
        return nullptr;
    }

    ListNode *head = new ListNode(values[0]);
    ListNode *tail = head;

    for (int i = 1; i < (int)values.size(); i++) {
        tail->next = new ListNode(values[i]);
        tail = tail->next;
    }

    return head;
}

/* Helper: print the linked list in "a -> b -> c" format */
void printList(ListNode *head) {
    ListNode *current = head;
    while (current != nullptr) {
        cout << current->data;
        if (current->next != nullptr) {
            cout << " -> ";
        }
        current = current->next;
    }
    cout << endl;
}

/* Helper: free all nodes in the linked list */
void deleteList(ListNode *&head) {
    while (head != nullptr) {
        ListNode *temp = head;
        head = head->next;
        delete temp;
    }
}

int main() {
    /* Example 1 */
    vector<int> input1 = {1, 2, 3, 4, 5};

    ListNode *head1 = buildList(input1);

    cout << "Original list: ";
    printList(head1);

    Solution2 solution;
    head1 = solution.reverseList(head1);

