#include <iostream>
#include <vector>

using namespace std;

class ListNode {
  public:
    int data;
    ListNode *next;

    ListNode() : data(0), next(nullptr) {}

    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /* Brute Force Approach (Data Replacement):
       Count occurrences of 0, 1, and 2, then overwrite the list
       values in sorted order. Simple but modifies node data
       rather than rewiring links. */
    ListNode *sortList(ListNode *&head) {
        /* Nothing to sort for 0 or 1 node */
        if (head == nullptr || head->next == nullptr) {
            return head;
        }

        ListNode *current = head;

        /* Step 1: Count the frequency of each value (0, 1, 2) */
        int zeros{0};
        int ones{0};
        int twos{0};
        while (current != nullptr) {
            if (current->data == 0) {
                zeros++;
            } else if (current->data == 1) {
                ones++;
            } else {
                twos++;
            }
            current = current->next;
        }

        /* Step 2: Overwrite the list with sorted values.
           Place all 0's first, then all 1's, then all 2's. */
        current = head;
        while (zeros--) {
            current->data = 0;
            current = current->next;
        }
        while (ones--) {
            current->data = 1;
            current = current->next;
        }
        while (twos--) {
            current->data = 2;
            current = current->next;
        }

        return head;
    }

    /*
    Complexity Analysis

    Time Complexity: O(2N) — one pass to count, one pass to overwrite.
    Space Complexity: O(1) — only three integer counters used.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (Pointer Rewiring with Dummy Nodes):
       Maintain three separate chains — one for 0s, one for 1s, one for 2s.
       Traverse the list once, appending each node to the appropriate chain,
       then stitch the three chains together. No data overwriting needed. */
    ListNode *sortList(ListNode *&head) {
        /* Nothing to sort for 0 or 1 node */
        if (head == nullptr || head->next == nullptr) {
            return head;
        }

        /* Create dummy heads for each chain so we don't need
           special-case logic for the first insertion. */
        ListNode *zerosHead = new ListNode(-1);
        ListNode *onesHead = new ListNode(-1);
        ListNode *twosHead = new ListNode(-1);

        /* Tail pointers — these move forward as we append nodes */
        ListNode *zeros_current = zerosHead;
        ListNode *ones_current = onesHead;
        ListNode *twos_current = twosHead;

        ListNode *current = head;

        /* Step 1: Distribute every node into the matching chain */
        while (current != nullptr) {
            if (current->data == 0) {
                zeros_current->next = current;
                zeros_current = zeros_current->next;
            } else if (current->data == 1) {
                ones_current->next = current;
                ones_current = ones_current->next;
            } else {
                twos_current->next = current;
                twos_current = twos_current->next;
            }

            current = current->next;
        }

        /* Step 2: Stitch the three chains together.
           - 0-chain tail → first real node of the 1-chain (or 2-chain if no 1s exist)
           - 1-chain tail → first real node of the 2-chain
           - 2-chain tail → nullptr (terminates the list) */
        zeros_current->next = onesHead->next ? onesHead->next : twosHead->next;
        ones_current->next = twosHead->next;
        twos_current->next = nullptr;

        /* The new head is the first real node after the 0-chain dummy */
        ListNode *newHead = zerosHead->next;

        /* Clean up the dummy sentinel nodes */
        delete zerosHead;
        delete onesHead;
        delete twosHead;

        return newHead;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — single pass through the list to distribute nodes.
    Space Complexity: O(1) — only a fixed number of pointers used
                      (the three dummy nodes are constant extra space).
    */
};

/* Helper: build a linked list from a vector of values */
ListNode *buildList(const vector<int> &values) {
    if (values.empty()) {
        return nullptr;
    }

    ListNode *head = new ListNode(values[0]);
    ListNode *tail = head;

    for (int i = 1; i < values.size(); i++) {
        tail->next = new ListNode(values[i]);
        tail = tail->next;
    }

    return head;
}

/* Helper: print the linked list in "a -> b -> c" format */
void printList(ListNode *head) {
    ListNode *current = head;
    while (current != nullptr) {
        cout << current->data;
        if (current->next != nullptr) {
            cout << " -> ";
        }
        current = current->next;
    }
    cout << endl;
}

/* Helper: free all nodes in the linked list */
void deleteList(ListNode *&head) {
    while (head != nullptr) {
        ListNode *temp = head;
        head = head->next;
        delete temp;
    }
}

int main() {
    vector<int> input = {1, 0, 2, 0, 1};

    ListNode *head = buildList(input);

    cout << "Original list: ";
    printList(head);

