#include <iostream>
#include <unordered_map>
#include <vector>

using namespace std;

class ListNode {
  public:
    int data;
    ListNode *next;
    ListNode *random;

    ListNode() : data(0), next(nullptr), random(nullptr) {}

    ListNode(int x) : data(x), next(nullptr), random(nullptr) {}

    ListNode(int x, ListNode *nextNode, ListNode *randomNode) : data(x), next(nextNode), random(randomNode) {}
};

class Solution {
  public:
    /* Brute Force Approach (Hash Map):
       1. First pass: create a clone for each original node and store
          the mapping original → clone in a hash map.
       2. Second pass: for each original node, set the clone's next and
          random pointers using the map to look up corresponding clones. */
    ListNode *copyRandomList(ListNode *head) {
        if (head == nullptr) {
            return head;
        }

        unordered_map<ListNode *, ListNode *> originalToClone;
        ListNode *current = head;

        /* Pass 1: Create all clone nodes (values only) */
        while (current != nullptr) {
            ListNode *cloneNode = new ListNode(current->data);
            originalToClone[current] = cloneNode;
            current = current->next;
        }

        /* Pass 2: Wire up next and random pointers on clones */
        current = head;
        while (current != nullptr) {
            ListNode *cloneNode = originalToClone[current];
            cloneNode->next = originalToClone[current->next];
            cloneNode->random = originalToClone[current->random];
            current = current->next;
        }

        return originalToClone[head];
    }

    /*
    Complexity Analysis

    Time Complexity: O(2N) — two passes over the list.
    Space Complexity: O(N) — hash map storing N original→clone pairs.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (Interleave, Connect, Extract):
       1. Insert clone nodes between each pair of original nodes.
       2. Use the interleaved structure to set random pointers on clones.
       3. Separate the interleaved list back into original and clone lists. */
    ListNode *copyRandomList(ListNode *head) {
        if (head == nullptr) {
            return head;
        }

        /* Step 1: Insert clone after each original node */
        insertCloneNodes(head);

        /* Step 2: Set random pointers on clone nodes */
        connectRandomPointers(head);

        /* Step 3: Separate into original and cloned lists */
        return extractCloneList(head);
    }

    /* Insert a clone of each node immediately after it:
       A -> B  becomes  A -> A' -> B -> B' */
    void insertCloneNodes(ListNode *head) {
        ListNode *current = head;

        while (current != nullptr) {
            ListNode *nextOriginal = current->next;

            ListNode *cloneNode = new ListNode(current->data);
            current->next = cloneNode;
            cloneNode->next = nextOriginal;

            current = nextOriginal;
        }
    }

    /* For each original node, set clone->random = original->random->next
       (the clone of the random target) */
    void connectRandomPointers(ListNode *head) {
        ListNode *current = head;

        while (current != nullptr) {
            ListNode *cloneNode = current->next;
            cloneNode->random = (current->random != nullptr) ? current->random->next : nullptr;
            current = cloneNode->next;
        }
    }

    /* Separate the interleaved list into original and clone lists */
    ListNode *extractCloneList(ListNode *head) {
        ListNode *current = head;
        ListNode *dummy = new ListNode(-1);
        ListNode *tail = dummy;

        while (current != nullptr) {
            ListNode *cloneNode = current->next;

            /* Attach clone to the result list */
            tail->next = cloneNode;
            tail = tail->next;

            /* Restore original list's next pointer */
            current->next = cloneNode->next;
            current = current->next;
        }

        /* Clean up the dummy node before returning */
        ListNode *cloneHead = dummy->next;
        delete dummy;
        return cloneHead;
    }

    /*
    Complexity Analysis

    Time Complexity: O(3N) — three passes (insert, connect random, extract).
    Space Complexity: O(1) — no extra data structures; clone nodes are the output.
    */
};

/* Helper: build a linked list with random pointers from [val, random_index] pairs.
   random_index = -1 means random is null. */
ListNode *buildRandomList(const vector<pair<int, int>> &nodes) {
    if (nodes.empty()) {
        return nullptr;
    }

    vector<ListNode *> nodeList;

    /* Create all nodes */
    for (const auto &[val, _] : nodes) {
        nodeList.push_back(new ListNode(val));
    }

    /* Wire next pointers */
    for (int i = 0; i < (int)nodeList.size() - 1; i++) {
        nodeList[i]->next = nodeList[i + 1];
    }

    /* Wire random pointers */
    for (int i = 0; i < (int)nodes.size(); i++) {
        int randIdx = nodes[i].second;
        if (randIdx != -1) {
            nodeList[i]->random = nodeList[randIdx];
        }
    }

    return nodeList[0];
}

/* Helper: verify the clone is correct and independent */
bool verifyClone(ListNode *original, ListNode *clone) {
    ListNode *o = original;
    ListNode *c = clone;

    while (o != nullptr && c != nullptr) {
        /* Values must match */
        if (o->data != c->data)
            return false;
        /* Nodes must be different objects */
        if (o == c)
            return false;
        /* Random targets must have same value (or both null) */
        if (o->random == nullptr && c->random != nullptr)
            return false;
        if (o->random != nullptr && c->random == nullptr)
            return false;
        if (o->random != nullptr && o->random->data != c->random->data)
            return false;

        o = o->next;
        c = c->next;
    }

    return (o == nullptr && c == nullptr);
}

/* Helper: print list values */
void printRandomList(ListNode *head) {
    ListNode *current = head;
    while (current != nullptr) {
        cout << current->data;
        if (current->next != nullptr) {
            cout << " -> ";
        }
        current = current->next;
    }
    cout << endl;
}

/* Helper: free all nodes */
void deleteRandomList(ListNode *&head) {
    while (head != nullptr) {
        ListNode *temp = head;
        head = head->next;
        delete temp;
    }
}

int main() {
    Solution2 solution;

    /* Example 1: [[1,-1],[2,0],[3,4],[4,1],[5,2]] */
    ListNode *head1 = buildRandomList({{1, -1}, {2, 0}, {3, 4}, {4, 1}, {5, 2}});

    cout << "Original: ";
    printRandomList(head1);

    ListNode *clone1 = solution.copyRandomList(head1);

    cout << "Clone:    ";
    printRandomList(clone1);
    cout << "Valid:    " << (verifyClone(head1, clone1) ? "true" : "false") << endl;

    deleteRandomList(head1);
    deleteRandomList(clone1);

    /* Example 2: [[5,-1],[3,-1],[2,1],[1,1]] */
    ListNode *head2 = buildRandomList({{5, -1}, {3, -1}, {2, 1}, {1, 1}});

    cout << "\nOriginal: ";
    printRandomList(head2);

    ListNode *clone2 = solution.copyRandomList(head2);

    cout << "Clone:    ";
    printRandomList(clone2);
    cout << "Valid:    " << (verifyClone(head2, clone2) ? "true" : "false") << endl;

    deleteRandomList(head2);
    deleteRandomList(clone2);

    return 0;
}

#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

class ListNode {
  public:
    int data;
    ListNode *next;
    ListNode *child;

    ListNode() : data(0), next(nullptr), child(nullptr) {}

    ListNode(int x) : data(x), next(nullptr), child(nullptr) {}

    ListNode(int x, ListNode *nextNode, ListNode *childNode) : data(x), next(nextNode), child(childNode) {}
};

class Solution {
  public:
    /* Brute Force Approach (Collect, Sort, Rebuild):
       Traverse all nodes via next and child pointers, collect values
       into an array, sort it, then build a new flattened list via child. */
    ListNode *flattenLinkedList(ListNode *head) {
        vector<int> arr;
        ListNode *column = head;

        /* Step 1: Walk each top-level node via 'next' */
        while (column != nullptr) {
            ListNode *current = column;

            /* Step 2: Walk down each sub-list via 'child' */
            while (current != nullptr) {
                arr.push_back(current->data);
                current = current->child;
            }
            column = column->next;
        }

        /* Step 3: Sort all collected values */
        sort(arr.begin(), arr.end());

        /* Step 4: Build a new flattened list linked via 'child' */
        ListNode *dummy = new ListNode(-1);
        ListNode *current = dummy;

        for (int i = 0; i < (int)arr.size(); i++) {
            current->child = new ListNode(arr[i]);
            current = current->child;
        }

        /* Clean up the dummy node before returning */
        ListNode *result = dummy->child;
        delete dummy;
        return result;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N×M log(N×M)) — collecting all N×M values is O(N×M), sorting dominates.
    Space Complexity: O(N×M) — array to store all values + new list nodes.

    where N = number of top-level nodes (next), M = average sub-list length (child).
    */
};

class Solution2 {
  public:
    /* Optimized Approach (Recursive Merge from Right):
       Recursively flatten from the last sub-list back to the first.
       At each step, merge the current sub-list with the already-flattened
       remainder using a two-pointer sorted merge via the 'child' pointer. */
    ListNode *flattenLinkedList(ListNode *head) {
        /* Base case: single sub-list or empty — already flat */
        if (head == nullptr || head->next == nullptr) {
            return head;
        }

        /* Recursively flatten everything from head->next onward */
        ListNode *mergedHead = flattenLinkedList(head->next);

        /* Merge current sub-list with the flattened remainder */
        head = merge(head, mergedHead);

        return head;
    }

    /* Helper: merge two sorted child-linked lists into one */
    ListNode *merge(ListNode *list1, ListNode *list2) {
        ListNode *dummy = new ListNode(-1);
        ListNode *tail = dummy;

        /* Compare and attach the smaller node at each step */
        while (list1 != nullptr && list2 != nullptr) {
            if (list1->data <= list2->data) {
                tail->child = list1;
                list1 = list1->child;
            } else {
                tail->child = list2;
                list2 = list2->child;
            }
            tail = tail->child;
        }

        /* Attach the remaining nodes */
        if (list1 != nullptr) {
            tail->child = list1;
        }

        if (list2 != nullptr) {
            tail->child = list2;
        }

        /* Disconnect the merged head from the top-level 'next' chain */
        if (dummy->child) {
            dummy->child->next = nullptr;
        }

        /* Clean up the dummy node before returning */
        ListNode *result = dummy->child;
        delete dummy;
        return result;
    }

    /*
    Complexity Analysis

    Time Complexity: O(M × N²) — each merge grows: O(M) + O(2M) + … + O(NM) = O(M × N²).
    Space Complexity: O(N) — recursion stack depth equals the number of top-level nodes.

    where N = number of top-level nodes (next), M = average sub-list length (child).
    */
};

/* Helper: build the special linked list from nested vectors.
   Each inner vector is a sub-list connected via 'child'.
   Top-level nodes are connected via 'next'. */
ListNode *buildFlattenList(const vector<vector<int>> &lists) {
    if (lists.empty()) {
        return nullptr;
    }

    vector<ListNode *> heads;

    for (const auto &sublist : lists) {
        if (sublist.empty()) {
            continue;
        }

        ListNode *head = new ListNode(sublist[0]);
        ListNode *current = head;

        for (int i = 1; i < (int)sublist.size(); i++) {
            current->child = new ListNode(sublist[i]);
            current = current->child;
        }

        heads.push_back(head);
    }

    /* Link top-level heads via 'next' */
    for (int i = 0; i < (int)heads.size() - 1; i++) {
        heads[i]->next = heads[i + 1];
    }

    return heads.empty() ? nullptr : heads[0];
}

/* Helper: print flattened list connected via 'child' */
void printFlatList(ListNode *head) {
    ListNode *current = head;
    while (current != nullptr) {
        cout << current->data;
        if (current->child != nullptr) {
            cout << " -> ";
        }
        current = current->child;
    }
    cout << endl;
}

/* Helper: free all nodes (both next and child directions) */
void deleteFlattenList(ListNode *head) {
    while (head != nullptr) {
        ListNode *nextCol = head->next;
        ListNode *current = head;

        while (current != nullptr) {
            ListNode *temp = current;
            current = current->child;
            delete temp;
        }

        head = nextCol;
    }
}

/* Helper: free a flattened (child-only) list */
void deleteFlatList(ListNode *&head) {
    while (head != nullptr) {
        ListNode *temp = head;
        head = head->child;
        delete temp;
    }
}

int main() {
    Solution2 solution;

    /* Example 1 */
    ListNode *head1 = buildFlattenList({{3}, {2, 10}, {1, 7, 11, 12}, {4, 9}, {5, 6, 8}});

    cout << "Flattened: ";
    ListNode *result1 = solution.flattenLinkedList(head1);
    printFlatList(result1);

    deleteFlatList(result1);

    /* Example 2 */
    ListNode *head2 = buildFlattenList({{2, 13, 17}, {4, 5, 16, 20}, {10, 12}});

    cout << "Flattened: ";
    ListNode *result2 = solution.flattenLinkedList(head2);
    printFlatList(result2);

    deleteFlatList(result2);

    return 0;
}

#include <algorithm>
