using namespace std;

class ListNode {
  public:
    int data;
    ListNode *next;

    ListNode() : data(0), next(nullptr) {}

    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /* Brute Force Approach (Collect, Sort, Rebuild):
       Collect all values from both lists into an array, sort the array,
       then build a new linked list from the sorted values. */
    ListNode *mergeTwoLists(ListNode *list1, ListNode *list2) {
        vector<int> arr;
        ListNode *current = list1;

        /* Step 1: Collect all values from list1 */
        while (current != nullptr) {
            arr.push_back(current->data);
            current = current->next;
        }

        /* Step 2: Collect all values from list2 */
        current = list2;
        while (current != nullptr) {
            arr.push_back(current->data);
            current = current->next;
        }

        /* Step 3: Sort the combined values */
        sort(arr.begin(), arr.end());

        /* Step 4: Build a new linked list from the sorted array */
        ListNode *dummy = new ListNode(-1);
        current = dummy;

        for (int i = 0; i < (int)arr.size(); i++) {
            current->next = new ListNode(arr[i]);
            current = current->next;
        }

        /* Clean up the dummy node before returning */
        ListNode *head = dummy->next;
        delete dummy;
        return head;
    }

    /*
    Complexity Analysis

    Time Complexity: O((N + M) log(N + M)) — collecting is O(N + M), sorting dominates.
    Space Complexity: O(N + M) — array to store all values + new list nodes.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (Two-Pointer Merge):
       Use a dummy node and a tail pointer. Compare the front nodes
       of both lists, attach the smaller one to the tail, and advance.
       When one list is exhausted, attach the remainder of the other. */
    ListNode *mergeTwoLists(ListNode *list1, ListNode *list2) {
        ListNode *current1 = list1;
        ListNode *current2 = list2;
        ListNode *dummy = new ListNode(-1);
        ListNode *tail = dummy;

        /* Compare and attach the smaller node at each step */
        while (current1 != nullptr && current2 != nullptr) {
            if (current1->data <= current2->data) {
                tail->next = current1;
                current1 = current1->next;
            } else {
                tail->next = current2;
                current2 = current2->next;
            }
            tail = tail->next;
        }

        /* Attach the remaining nodes from whichever list is non-empty */
        if (current1 != nullptr) {
            tail->next = current1;
        }

        if (current2 != nullptr) {
            tail->next = current2;
        }

        /* Clean up the dummy node before returning */
        ListNode *head = dummy->next;
        delete dummy;
        return head;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N + M) — each node is visited at most once.
    Space Complexity: O(1) — only pointers used; nodes are reused, not copied.
    */
};

/* Helper: build a linked list from a vector of values */
ListNode *buildList(const vector<int> &values) {
    if (values.empty()) {
