#include <iostream>
#include <vector>

using namespace std;

class ListNode {
  public:
    int data;
    ListNode *next;

    ListNode() : data(0), next(nullptr) {}

    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /* Brute Force Approach (Copy to Array):
       Copy all values to an array, reverse sub-arrays of size k,
       then write the values back to the list.
       Note: This modifies node data rather than rewiring links. */
    ListNode *reverseKGroup(ListNode *head, int k) {
        vector<int> arr;
        ListNode *current = head;

        /* Step 1: Collect all node values */
        while (current != nullptr) {
            arr.push_back(current->data);
            current = current->next;
        }

        int list_length = arr.size();

        /* Step 2: Reverse every group of k elements in the array.
           Skip the remaining elements if fewer than k are left. */
        for (int i = 0; i < list_length; i++) {
            if (list_length - i >= k) {
                reverseArray(arr, i, i + k - 1);
                i = i + k - 1; // skip to the end of the reversed group
            }
        }

        /* Step 3: Write the reordered values back to the list */
        current = head;
        for (int i = 0; i < list_length; i++) {
            current->data = arr[i];
            current = current->next;
        }

        return head;
    }

    /* Helper: reverse elements in arr from index start to end */
    void reverseArray(vector<int> &arr, int start, int end) {
        for (int i = start, j = end; i < j; i++, j--) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    /*
    Complexity Analysis

    Time Complexity: O(2N) — one pass to copy, one pass to write back (reversals are O(N) total).
    Space Complexity: O(N) — extra array to store all node values.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (In-Place Pointer Rewiring):
       Process the list in groups of k:
       1. Find the k-th node from current. If fewer than k remain, stop.
       2. Detach the group by nulling the k-th node's next pointer.
       3. Reverse the isolated group in-place.
       4. After reversal, kThNode is the new group head, current is the new tail.
       5. Link the previous group's tail to the new head.
       6. Move forward to the next group. */
    ListNode *reverseKGroup(ListNode *head, int k) {
        ListNode *current = head;
        ListNode *prevGroupTail = nullptr;

        while (current != nullptr) {
            /* Find the k-th node starting from current */
            ListNode *kThNode = getKThNode(current, k);

            /* Fewer than k nodes left — link them as-is and stop */
            if (kThNode == nullptr) {
                if (prevGroupTail) {
                    prevGroupTail->next = current;
                }
                break;
            }

            /* Save the start of the next group before detaching */
            ListNode *nextGroupHead = kThNode->next;
            kThNode->next = nullptr; // detach the group

            /* Reverse the isolated group */
            reverseLinkedList(current);

            /* After reversal: kThNode is the new head, current is the new tail.
               Link the previous group's tail to the new head. */
            if (current == head) {
                head = kThNode; // first group — update the list head
            } else {
                prevGroupTail->next = kThNode;
            }

            prevGroupTail = current; // current is now the tail of this reversed group
            current = nextGroupHead; // move to the next group
        }

        return head;
    }

    /* Helper: find the k-th node starting from current (1-based) */
    ListNode *getKThNode(ListNode *current, int k) {
        k--;
        while (current != nullptr && k > 0) {
            current = current->next;
            k--;
        }
        return current;
    }

    /* Helper: iterative in-place reversal */
    ListNode *reverseLinkedList(ListNode *head) {
        ListNode *current = head;
        ListNode *prev = nullptr;
        ListNode *front = nullptr;

        while (current != nullptr) {
            front = current->next;
            current->next = prev;
            prev = current;
            current = front;
        }

        return prev;
    }

    /*
    Complexity Analysis

    Time Complexity: O(2N) — each node is visited once to find k-th nodes and once to reverse.
    Space Complexity: O(1) — only pointers used, no extra data structures.
    */
};

