class Solution {
  public:
    /* Brute Force Approach (Rotate One at a Time):
       For each of the k rotations, traverse to the second-to-last node,
       detach the tail, and move it to the front as the new head. */
    ListNode *rotateRight(ListNode *head, int k) {
        if (head == nullptr || head->next == nullptr || k == 0) {
            return head;
        }

        /* Perform k individual right rotations */
        for (int i = 0; i < k; i++) {
            ListNode *current = head;

            /* Traverse to the second-to-last node */
            while (current->next->next != nullptr) {
                current = current->next;
            }

            /* Detach the tail and make it the new head */
            ListNode *tail = current->next;
            current->next = nullptr;
            tail->next = head;
            head = tail;
        }

        return head;
    }

    /*
    Complexity Analysis

    Time Complexity: O(k × N) — for each of the k rotations, traverse the entire list.
    Space Complexity: O(1) — only pointers used.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (Make Circular, Then Break):
       1. Traverse to the tail and compute the list length.
       2. Connect the tail to the head to form a circular list.
       3. Reduce k using modulo (k % length) to handle k > length.
       4. Advance (length - k) steps from the tail to reach the new tail.
       5. The next node becomes the new head; break the circle. */
    ListNode *rotateRight(ListNode *head, int k) {
        if (head == nullptr || head->next == nullptr || k == 0) {
            return head;
        }

        /* Step 1: Find the tail and compute list length */
        ListNode *current = head;
        int length = 1;
        while (current->next != nullptr) {
            current = current->next;
            length++;
        }

        /* Step 2: Make the list circular */
        current->next = head;

        /* Step 3: Compute effective rotation and find the new tail */
        k = k % length;
        int stepsToNewTail = length - k;
        while (stepsToNewTail--) {
            current = current->next;
        }

        /* Step 4: Break the circle at the new tail */
        head = current->next;
        current->next = nullptr;

        return head;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — one full traversal to find the tail + at most N steps to find the new tail.
    Space Complexity: O(1) — only pointers used.
    */
};

