#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

class ListNode {
  public:
    int data;
    ListNode *next;

    ListNode() : data(0), next(nullptr) {}

    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /* Brute Force Approach (Copy to Array, Sort, Write Back):
       Collect all node values into an array, sort it, then overwrite
       the linked list node values with the sorted order. */
    ListNode *sortList(ListNode *head) {
        vector<int> arr;
        ListNode *current = head;

        /* Step 1: Collect all node values */
        while (current != nullptr) {
            arr.push_back(current->data);
            current = current->next;
        }

        /* Step 2: Sort the collected values */
        sort(arr.begin(), arr.end());

        /* Step 3: Write sorted values back to the list */
        current = head;
        for (int i = 0; i < (int)arr.size(); i++) {
            current->data = arr[i];
            current = current->next;
        }

        return head;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N log N) — collecting is O(N), sorting dominates.
    Space Complexity: O(N) — extra array to store all node values.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (Merge Sort):
       1. Find the middle of the list to split it into two halves.
       2. Recursively sort each half.
       3. Merge the two sorted halves using a two-pointer merge. */
    ListNode *sortList(ListNode *head) {
        /* Base case: empty or single node — already sorted */
        if (head == nullptr || head->next == nullptr) {
            return head;
        }

        /* Split the list into two halves at the middle */
        ListNode *middle = findMiddle(head);

        ListNode *right = middle->next;
        middle->next = nullptr; // detach the right half
        ListNode *left = head;

        /* Recursively sort both halves */
        left = sortList(left);
        right = sortList(right);

        /* Merge the two sorted halves */
        return mergeTwoSortedLists(left, right);
    }

    /* Helper: find the first middle node (for even-length, the left-center).
       Starting fast one step ahead ensures slow lands on the first middle. */
    ListNode *findMiddle(ListNode *head) {
        if (head == nullptr || head->next == nullptr) {
            return head;
        }
        ListNode *slow = head;
        /* Starting fast one step ahead so that for even-length lists,
           slow stops at the left-center (first middle). If fast started
           at head, slow would land on the second middle — making the
           left half equal to the original list for a 2-node list,
           causing infinite recursion. */
        ListNode *fast = head->next;

        while (fast != nullptr && fast->next != nullptr) {
            slow = slow->next;
            fast = fast->next->next;
        }

        return slow;
    }

    /* Helper: merge two sorted lists into one */
    ListNode *mergeTwoSortedLists(ListNode *list1, ListNode *list2) {
        ListNode *dummy = new ListNode(-1);
        ListNode *tail = dummy;

        /* Compare and attach the smaller node at each step */
        while (list1 != nullptr && list2 != nullptr) {
            if (list1->data <= list2->data) {
                tail->next = list1;
                list1 = list1->next;
            } else {
                tail->next = list2;
                list2 = list2->next;
            }
            tail = tail->next;
        }

        /* Attach the remaining nodes */
        if (list1 != nullptr) {
            tail->next = list1;
        }

        if (list2 != nullptr) {
            tail->next = list2;
        }

        /* Clean up the dummy node before returning */
        ListNode *head = dummy->next;
        delete dummy;
        return head;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N log N) — list is split log N times, each level merges all N nodes.
    Space Complexity: O(log N) — recursion stack depth.
    */
};

/* Helper: build a linked list from a vector of values */
ListNode *buildList(const vector<int> &values) {
    if (values.empty()) {
        return nullptr;
    }

    ListNode *head = new ListNode(values[0]);
    ListNode *tail = head;

    for (int i = 1; i < (int)values.size(); i++) {
        tail->next = new ListNode(values[i]);
        tail = tail->next;
    }

