class ListNode {
  public:
    int data;
    ListNode *next;

    ListNode() : data(0), next(nullptr) {}

    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /* Approach (Reverse → Add → Reverse):
       Since addition propagates from the least-significant digit,
       reverse the list first so we can process it left-to-right,
       add one with carry propagation, then reverse back. */
    ListNode *addOne(ListNode *head) {
        /* Step 1: Reverse to get least-significant digit at the front */
        head = reverseList(head);

        ListNode *current = head;

        int carry = 1; // we're adding 1, so initial carry is 1
        int sum{0};

        /* Step 2: Walk through the reversed list, propagating the carry.
           Note: the `|| carry` in the condition is safely guarded by the
           early break below — we always create a new node for leftover carry
           before current becomes nullptr. */
        while (current != nullptr || carry) {
            sum = carry + current->data;
            current->data = sum % 10; // digit stays in 0–9
            carry = sum / 10;         // carry is 0 or 1

            /* If this is the last node and there's still a carry,
               append a new node (e.g. 999 + 1 → 0001 reversed) */
            if (current->next == nullptr && carry) {
                current->next = new ListNode(carry);
                break;
            }
            current = current->next;
        }

        /* Step 3: Reverse back to restore most-significant digit first */
        return reverseList(head);
    }

    /* Helper: iterative in-place reversal */
    ListNode *reverseList(ListNode *head) {
        if (head == nullptr || head->next == nullptr) {
            return head;
        }

        ListNode *current = head;
        ListNode *prev = nullptr;

        while (current != nullptr) {
            ListNode *front = current->next;
            current->next = prev;
            prev = current;
            current = front;
        }

        return prev;
    }

    /*
    Complexity Analysis

    Time Complexity: O(3N) — reverse (N) + add with carry (N) + reverse back (N).
    Space Complexity: O(1) — in-place reversal, only a few pointers used
                      (one extra node allocated only when all digits are 9).
    */
};

