    if (values.empty()) {
        return nullptr;
    }

    ListNode *head = new ListNode(values[0]);
    ListNode *tail = head;

    for (int i = 1; i < (int)values.size(); i++) {
        tail->next = new ListNode(values[i]);
        tail = tail->next;
    }

    return head;
}

