#include <iostream>
#include <vector>

using namespace std;

class ListNode {
  public:
    int data;
    ListNode *next;

    ListNode() : data(0), next(nullptr) {}

    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /* Brute Force Approach (Two-Pass):
       First pass counts the total length.
       Second pass walks to the node just before the middle and removes it. */
    ListNode *deleteMiddle(ListNode *head) {
        /* Single node — delete it and return empty list */
        if (head->next == nullptr) {
            delete head;
            return nullptr;
        }

        ListNode *current = head;
        int list_length{0};

        /* Step 1: Count the total number of nodes */
        while (current != nullptr) {
            list_length++;
            current = current->next;
        }

        /* Step 2: Middle index is ⌊n/2⌋ + 1 (1-based).
           We need to stop one node before it, i.e. at index mid_idx - 1. */
        int mid_idx = (list_length / 2) + 1;
        current = head;
        for (int i = 1; i < mid_idx - 1; i++) {
            current = current->next;
        }

        /* Step 3: Unlink the middle node and free its memory */
        ListNode *midNode = current->next;
        current->next = midNode->next;
        delete midNode;

        return head;
    }

    /*
    Complexity Analysis

    Time Complexity: O(2N) — one pass to count, one pass to reach the predecessor.
    Space Complexity: O(1) — only a pointer and a counter used.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (Slow & Fast Pointers):
       slow moves 1 step, fast moves 2 steps. When fast reaches the end,
       slow is at the middle. A trailing prev_slowp pointer keeps track
       of the node before slow so we can unlink the middle. */
    ListNode *deleteMiddle(ListNode *head) {
        /* Single node — delete it and return empty list */
        if (head->next == nullptr) {
            delete head;
            return nullptr;
        }

        ListNode *slowp = head;
        ListNode *prev_slowp = nullptr; // trails one step behind slow
        ListNode *fastp = head;

        /* When fast reaches the end, slow is at the middle.
           prev_slowp stays one node behind slow for unlinking. */
        while (fastp != nullptr && fastp->next != nullptr) {
            prev_slowp = slowp;
            slowp = slowp->next;
            fastp = fastp->next->next;
        }

        /* slow is now the middle node — unlink and free it */
        ListNode *midNode = slowp;
        prev_slowp->next = midNode->next;
        delete midNode;

        return head;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N/2) — fast pointer traverses the list in half the iterations.
    Space Complexity: O(1) — only three pointers used.
    */
};

/* Helper: build a linked list from a vector of values */
ListNode *buildList(const vector<int> &values) {
    if (values.empty()) {
        return nullptr;
    }

    ListNode *head = new ListNode(values[0]);
    ListNode *tail = head;

    for (int i = 1; i < (int)values.size(); i++) {
        tail->next = new ListNode(values[i]);
        tail = tail->next;
    }

    return head;
}

/* Helper: print the linked list in "a -> b -> c" format */
void printList(ListNode *head) {
    ListNode *current = head;
    while (current != nullptr) {
        cout << current->data;
        if (current->next != nullptr) {
            cout << " -> ";
        }
        current = current->next;
    }
    cout << endl;
}

/* Helper: free all nodes in the linked list */
void deleteList(ListNode *&head) {
    while (head != nullptr) {
        ListNode *temp = head;
        head = head->next;
        delete temp;
    }
}

int main() {
    /* Example 1: odd-length list */
    vector<int> input1 = {1, 2, 3, 4, 5};

    ListNode *head1 = buildList(input1);

    cout << "Original list: ";
    printList(head1);

    Solution solution;
    head1 = solution.deleteMiddle(head1);

    cout << "After deleting middle: ";
    printList(head1);

    deleteList(head1);

    /* Example 2: even-length list */
    vector<int> input2 = {7, 6, 5, 4};

    ListNode *head2 = buildList(input2);

    cout << "\nOriginal list: ";
    printList(head2);

