#include <iostream>
#include <unordered_set>
#include <vector>

using namespace std;

class ListNode {
  public:
    int data;
    ListNode *next;

    ListNode() : data(0), next(nullptr) {}

    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /* Brute Force Approach (Hash Set):
       Walk the list, storing each visited node's address in a set.
       If we encounter a node already in the set, a cycle exists. */
    bool hasCycle(ListNode *head) {
        unordered_set<ListNode *> visited;

        ListNode *current = head;

        /* Traverse the list — if current is already visited,
           we've looped back, so a cycle exists. */
        while (current != nullptr) {
            if (visited.count(current)) {
                return true;
            }
            visited.insert(current);
            current = current->next;
        }

        /* Reached the end (nullptr) — no cycle */
        return false;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — each node visited at most once.
    Space Complexity: O(N) — hash set stores up to N node addresses.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (Floyd's Tortoise and Hare):
       Two pointers start at head — slow moves 1 step, fast moves 2 steps.
       If a cycle exists, fast will eventually lap slow and they'll meet
       inside the cycle. If no cycle, fast reaches nullptr. */
    bool hasCycle(ListNode *head) {
        ListNode *slow = head;
        ListNode *fast = head;

        /* fast checks two nodes per iteration:
           - fast != nullptr       → guards fast->next access
           - fast->next != nullptr → guards fast->next->next access */
        while (fast != nullptr && fast->next != nullptr) {
            slow = slow->next;
            fast = fast->next->next;

            /* Collision — slow and fast met inside the cycle */
            if (slow == fast) {
                return true;
            }
        }

        /* fast reached the end — no cycle */
        return false;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — in a cycle, fast catches slow within one full loop.
    Space Complexity: O(1) — only two pointers used.
    */
};

/* Helper: build a linked list from a vector and optionally create a cycle.
   If pos >= 0, the tail's next points to the node at that index. */
ListNode *buildListWithCycle(const vector<int> &values, int pos) {
    if (values.empty()) {
        return nullptr;
    }

    ListNode *head = new ListNode(values[0]);
    ListNode *tail = head;
    ListNode *cycleTarget = (pos == 0) ? head : nullptr;

    for (int i = 1; i < (int)values.size(); i++) {
        tail->next = new ListNode(values[i]);
        tail = tail->next;
        if (i == pos) {
            cycleTarget = tail;
        }
    }

    /* Create the cycle by linking the tail to the target node */
    if (pos >= 0 && cycleTarget != nullptr) {
        tail->next = cycleTarget;
    }

    return head;
}

/* Helper: print a linked list (safe for cycles — prints up to limit nodes) */
void printList(ListNode *head, int limit = 20) {
    ListNode *current = head;
    int count = 0;
    while (current != nullptr && count < limit) {
        cout << current->data;
        if (current->next != nullptr && count < limit - 1) {
            cout << " -> ";
        }
        current = current->next;
        count++;
    }
    if (current != nullptr) {
        cout << " -> ...";
    }
    cout << endl;
}

/* Helper: free a list with a potential cycle (break cycle first) */
void deleteListWithCycle(ListNode *head) {
    /* Detect and break the cycle using slow/fast pointers */
    ListNode *slow = head;
    ListNode *fast = head;
    bool hasCycle = false;

    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            hasCycle = true;
            break;
        }
    }

    if (hasCycle) {
        /* Find the start of the cycle and break it */
        slow = head;
        while (slow != fast) {
            slow = slow->next;
            fast = fast->next;
        }
        /* fast is now at the cycle start — find the node whose next is fast */
        ListNode *prev = fast;
        while (prev->next != fast) {
            prev = prev->next;
        }
        prev->next = nullptr; // break the cycle
    }

    /* Now safely delete the acyclic list */
    while (head != nullptr) {
        ListNode *temp = head;
        head = head->next;
        delete temp;
    }
}

int main() {
    Solution solution;

    /* Example 1: cycle present — tail connects to index 1 */
    ListNode *head1 = buildListWithCycle({1, 2, 3, 4, 5}, 1);

    cout << "List (with cycle): ";
    printList(head1);

    cout << "Has cycle: " << (solution.hasCycle(head1) ? "true" : "false") << endl;

    deleteListWithCycle(head1);

    /* Example 2: no cycle */
    ListNode *head2 = buildListWithCycle({1, 3, 7, 4}, -1);

    cout << "\nList (no cycle): ";
    printList(head2);

    cout << "Has cycle: " << (solution.hasCycle(head2) ? "true" : "false") << endl;

    deleteListWithCycle(head2);

    return 0;
}

#include <iostream>
#include <unordered_set>
#include <vector>

using namespace std;

class ListNode {
  public:
    int data;
    ListNode *next;

    ListNode() : data(0), next(nullptr) {}

    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /* Brute Force Approach (Hash Set):
       Store all node addresses from listA in a set, then walk
       listB checking each node. The first match is the intersection. */
    ListNode *getIntersectionNode(ListNode *headA, ListNode *headB) {
        unordered_set<ListNode *> visited;
        ListNode *current = headA;

        /* Step 1: Insert every node of listA into the set */
        while (current != nullptr) {
            visited.insert(current);
            current = current->next;
        }

        /* Step 2: Walk listB — the first node found in the set
           is where the two lists merge. */
        current = headB;
        while (current != nullptr) {
            if (visited.count(current)) {
                return current;
            }
            current = current->next;
        }

        /* No intersection found */
        return nullptr;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N + M) — N nodes from listA inserted, M nodes from listB checked.
    Space Complexity: O(N) — hash set stores all nodes of listA.
    */
};

class Solution2 {
  public:
    /* Better Approach (Length Difference):
       1. Compute the lengths of both lists.
       2. Advance the longer list's pointer by the difference.
       3. Walk both pointers in lockstep — they'll meet at the
          intersection node (or both reach nullptr if no intersection). */
    ListNode *getIntersectionNode(ListNode *headA, ListNode *headB) {
        int lenA = getLength(headA);
        int lenB = getLength(headB);

        /* Always pass the shorter list first, longer list second */
        if (lenA < lenB) {
            return findCollision(headA, headB, lenB - lenA);
        } else {
            return findCollision(headB, headA, lenA - lenB);
        }
    }

    /* Helper: count the number of nodes in a list */
    int getLength(ListNode *head) {
        ListNode *current = head;
        int length{0};
        while (current != nullptr) {
            length++;
            current = current->next;
        }
        return length;
    }

    /* Helper: advance the longer list by the length difference,
       then walk both lists together until they collide. */
    ListNode *findCollision(ListNode *shortHead, ListNode *longHead, int diff) {
        ListNode *ptrShort = shortHead;
        ListNode *ptrLong = longHead;

        /* Skip ahead in the longer list so both have equal distance
           remaining to the potential intersection point */
        for (int i = 0; i < diff; i++) {
            ptrLong = ptrLong->next;
        }

        /* Walk in lockstep — if they intersect, they'll meet.
           If not, both reach nullptr together. */
        while (ptrShort != ptrLong) {
            ptrShort = ptrShort->next;
            ptrLong = ptrLong->next;
        }

        return ptrShort;
    }

    /*
    Complexity Analysis

    Time Complexity: O(2N + 2M) — two passes to get lengths, then one pass each to find collision.
    Space Complexity: O(1) — only pointers and counters used.
    */
};

class Solution3 {
  public:
    /* Optimized Approach (Two-Pointer Swap):
       Two pointers start at headA and headB respectively. When one
       reaches the end, it restarts at the OTHER list's head. After
       at most two passes, both pointers have traveled (lenA + lenB)
       nodes total, so they're guaranteed to align at the intersection
       node — or both reach nullptr if there's no intersection.

       Why it works:
       - ptrA travels: A's non-shared + shared + B's non-shared = lenA + lenB - shared
       - ptrB travels: B's non-shared + shared + A's non-shared = lenB + lenA - shared
       Both distances are equal, so they meet at the intersection. */
    ListNode *getIntersectionNode(ListNode *headA, ListNode *headB) {
        ListNode *ptrA = headA;
        ListNode *ptrB = headB;

        /* Walk both pointers. On reaching the end of one list,
           redirect to the head of the other list. They'll meet
           at the intersection or both become nullptr. */
        while (ptrA != ptrB) {
            ptrA = (ptrA == nullptr) ? headB : ptrA->next;
            ptrB = (ptrB == nullptr) ? headA : ptrB->next;
        }

        return ptrA;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N + M) — each pointer traverses at most both lists once.
    Space Complexity: O(1) — only two pointers used.
    */
};

/* Helper: build a linked list from a vector of values */
ListNode *buildList(const vector<int> &values) {
    if (values.empty()) {
        return nullptr;
    }

    ListNode *head = new ListNode(values[0]);
    ListNode *tail = head;

    for (int i = 1; i < (int)values.size(); i++) {
        tail->next = new ListNode(values[i]);
        tail = tail->next;
    }

    return head;
}

/* Helper: return the node at the given 0-based index */
ListNode *getNodeAt(ListNode *head, int index) {
    ListNode *current = head;
    for (int i = 0; i < index && current != nullptr; i++) {
        current = current->next;
    }
    return current;
}

/* Helper: print the linked list in "a -> b -> c" format */
void printList(ListNode *head) {
    ListNode *current = head;
    while (current != nullptr) {
        cout << current->data;
        if (current->next != nullptr) {
            cout << " -> ";
        }
        current = current->next;
    }
    cout << endl;
}

/* Helper: free nodes up to (but not including) a shared tail.
   Prevents double-free on the intersected portion. */
void deleteUpto(ListNode *head, ListNode *stop) {
    while (head != nullptr && head != stop) {
        ListNode *temp = head;
        head = head->next;
        delete temp;
    }
}

void deleteList(ListNode *&head) {
    while (head != nullptr) {
        ListNode *temp = head;
        head = head->next;
        delete temp;
    }
}

int main() {
    Solution3 solution;

    /* Example 1: lists intersect at node with value 4
       listA: 1 -> 2 -> 3 ↘
                             4 -> 5  (shared tail)
       listB:      7 -> 8 ↗                        */
    ListNode *shared = buildList({4, 5});

    ListNode *headA = buildList({1, 2, 3});
    getNodeAt(headA, 2)->next = shared; // attach shared tail

    ListNode *headB = buildList({7, 8});
    getNodeAt(headB, 1)->next = shared; // attach shared tail

    cout << "List A: ";
    printList(headA);
    cout << "List B: ";
    printList(headB);

    ListNode *result = solution.getIntersectionNode(headA, headB);
    cout << "Intersection: " << (result ? to_string(result->data) : "null") << endl;

    /* Free only the non-shared parts, then the shared tail once */
    deleteUpto(headA, shared);
    deleteUpto(headB, shared);
    deleteList(shared);

    /* Example 2: no intersection */
    ListNode *headC = buildList({1, 2, 3});
    ListNode *headD = buildList({8, 9});

    cout << "\nList A: ";
    printList(headC);
    cout << "List B: ";
    printList(headD);

    result = solution.getIntersectionNode(headC, headD);
    cout << "Intersection: " << (result ? to_string(result->data) : "null") << endl;

    deleteList(headC);
    deleteList(headD);

    return 0;
}

