    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /* Brute Force Approach (Hash Map with Timestamps):
       Walk the list, recording the step number when each node is first visited.
       If we revisit a node, the cycle length = current step - first visit step. */
    int findLengthOfLoop(ListNode *head) {
        unordered_map<ListNode *, int> visited;
        int step{0};
        ListNode *current = head;

        while (current != nullptr) {
            /* If this node was already visited, the difference
               in step counts gives the exact cycle length. */
            if (visited.count(current)) {
                return step - visited[current];
            }
            visited[current] = step;
            step++;
            current = current->next;
        }

        /* Reached nullptr — no cycle */
        return 0;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — each node visited at most once.
    Space Complexity: O(N) — hash map stores up to N entries.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (Floyd's Detection + Count):
       1. Detect the cycle using slow/fast pointers.
       2. Once they collide (both are inside the cycle), advance one
          pointer around the loop counting steps until it returns
          to the collision point. That count = cycle length. */
    int findLengthOfLoop(ListNode *head) {
        ListNode *slow = head;
        ListNode *fast = head;

        /* Step 1: Detect cycle */
        while (fast != nullptr && fast->next != nullptr) {
            slow = slow->next;
            fast = fast->next->next;

            if (slow == fast) {
                /* Step 2: Count the cycle length.
                   Move slow one step at a time from the collision point
                   until it loops back to fast (the same collision point). */
                slow = slow->next;
                int length{1};
                while (slow != fast) {
                    slow = slow->next;
                    length++;
                }
                return length;
            }
        }

        /* No cycle */
        return 0;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — detection takes O(N), counting the loop takes O(L) where L ≤ N.
    Space Complexity: O(1) — only two pointers and a counter used.
    */
};

/* Helper: build a linked list and optionally create a cycle.
   If pos >= 0, the tail's next points to the node at that index. */
ListNode *buildListWithCycle(const vector<int> &values, int pos) {
    if (values.empty()) {
        return nullptr;
    }

    ListNode *head = new ListNode(values[0]);
    ListNode *tail = head;
    ListNode *cycleTarget = (pos == 0) ? head : nullptr;

    for (int i = 1; i < (int)values.size(); i++) {
        tail->next = new ListNode(values[i]);
        tail = tail->next;
        if (i == pos) {
            cycleTarget = tail;
        }
    }

    if (pos >= 0 && cycleTarget != nullptr) {
        tail->next = cycleTarget;
    }

    return head;
}

