/* Helper: free a list with a potential cycle (break cycle first) */
void deleteListWithCycle(ListNode *head) {
    ListNode *slow = head;
    ListNode *fast = head;
    bool hasCycle = false;

    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            hasCycle = true;
            break;
        }
    }

    if (hasCycle) {
        slow = head;
        while (slow != fast) {
            slow = slow->next;
            fast = fast->next;
        }
        ListNode *prev = fast;
        while (prev->next != fast) {
            prev = prev->next;
        }
        prev->next = nullptr;
    }

    while (head != nullptr) {
        ListNode *temp = head;
        head = head->next;
        delete temp;
    }
}

