    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /* Brute Force Approach (Two-Pass):
       First pass counts the total length of the list.
       Second pass walks to the middle index: (length / 2) + 1.
       The + 1 after integer division ensures we land on the
       second middle node for even-length lists. */
    ListNode *middleOfLinkedList(ListNode *head) {
        /* Empty list — nothing to find */
        if (head == nullptr) {
            return head;
        }

        ListNode *current = head;
        int list_length{0};

        /* Step 1: Count the total number of nodes */
        while (current != nullptr) {
            list_length++;
            current = current->next;
        }

        /* Step 2: Calculate the 1-based middle index.
           e.g. length 5 → index 3, length 6 → index 4 (2nd middle) */
        int mid_ind = (list_length / 2) + 1;

        /* Step 3: Walk to the middle node */
        current = head;
        for (int i = 1; i < mid_ind; i++) {
            current = current->next;
        }

        return current;
    }

    /*
    Complexity Analysis

    Time Complexity: O(2N) — one pass to count, one pass to reach the middle.
    Space Complexity: O(1) — only a pointer and a counter used.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (Slow & Fast Pointers — Tortoise and Hare):
       slow moves 1 step, fast moves 2 steps per iteration.
       When fast reaches the end, slow is at the middle.
       For even-length lists, fast becomes nullptr and slow
       naturally lands on the 2nd middle node. */
    ListNode *middleOfLinkedList(ListNode *head) {
        ListNode *slowp = head;
        ListNode *fastp = head;

        /* fast moves twice as fast — when it finishes, slow is at the middle.
           - Odd length:  fast stops at the last node  → slow is the exact middle.
           - Even length: fast becomes nullptr          → slow is the 2nd middle. */
        while (fastp != nullptr && fastp->next != nullptr) {
            slowp = slowp->next;
            fastp = fastp->next->next;
        }

        return slowp;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N/2) — fast pointer traverses the list in half the iterations.
    Space Complexity: O(1) — only two pointers used.
    */
};

