#include <iostream>
#include <unordered_set>
#include <vector>

using namespace std;

class ListNode {
  public:
    int data;
    ListNode *next;

    ListNode() : data(0), next(nullptr) {}

    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /* Brute Force Approach (Hash Set):
       Walk the list, storing each visited node's address in a set.
       The first node we encounter that's already in the set is
       the starting point of the cycle. */
    ListNode *findStartingPoint(ListNode *head) {
        unordered_set<ListNode *> visited;

        ListNode *current = head;

        /* Traverse the list — the first revisited node is the cycle start */
        while (current != nullptr) {
            if (visited.count(current)) {
                return current;
            }
            visited.insert(current);
            current = current->next;
        }

        /* Reached nullptr — no cycle */
        return nullptr;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — each node visited at most once.
    Space Complexity: O(N) — hash set stores up to N node addresses.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (Floyd's Cycle Detection + Entry Point):
       1. Use slow/fast pointers to detect a cycle (they collide inside the loop).
       2. Reset slow to head. Walk both slow and fast one step at a time —
          they'll meet exactly at the cycle's starting node.

       Why it works:
       Let d = distance from head to cycle start,
           k = distance from cycle start to collision point,
           L = cycle length.
       At collision: slow traveled (d + k), fast traveled (d + k + nL).
       Since fast = 2 × slow → d + k = nL → d = nL - k.
       So moving d steps from head and d steps from collision point
       both land at the cycle start. */
    ListNode *findStartingPoint(ListNode *head) {
        ListNode *slow = head;
        ListNode *fast = head;

        /* Step 1: Detect cycle — slow moves 1 step, fast moves 2 steps */
        while (fast != nullptr && fast->next != nullptr) {
            slow = slow->next;
            fast = fast->next->next;

            if (slow == fast) {
                /* Step 2: Find the cycle start.
                   Reset slow to head, then walk both one step at a time. */
                slow = head;
                while (slow != fast) {
                    slow = slow->next;
                    fast = fast->next;
                }
                return slow;
            }
        }

        /* No cycle found */
        return nullptr;
    }

    /*
    Complexity Analysis

    Time Complexity: O(N) — detection takes O(N), finding the start takes O(N) at most.
    Space Complexity: O(1) — only two pointers used.
    */
};

/* Helper: build a linked list and optionally create a cycle.
   If pos >= 0, the tail's next points to the node at that index. */
ListNode *buildListWithCycle(const vector<int> &values, int pos) {
    if (values.empty()) {
        return nullptr;
    }

    ListNode *head = new ListNode(values[0]);
    ListNode *tail = head;
    ListNode *cycleTarget = (pos == 0) ? head : nullptr;

    for (int i = 1; i < (int)values.size(); i++) {
        tail->next = new ListNode(values[i]);
        tail = tail->next;
        if (i == pos) {
            cycleTarget = tail;
        }
    }

    if (pos >= 0 && cycleTarget != nullptr) {
        tail->next = cycleTarget;
    }

    return head;
}

/* Helper: print a linked list (safe for cycles — prints up to limit nodes) */
void printList(ListNode *head, int limit = 20) {
    ListNode *current = head;
    int count = 0;
    while (current != nullptr && count < limit) {
        cout << current->data;
        if (current->next != nullptr && count < limit - 1) {
            cout << " -> ";
        }
        current = current->next;
        count++;
    }
    if (current != nullptr) {
        cout << " -> ...";
    }
    cout << endl;
}

/* Helper: free a list with a potential cycle (break cycle first) */
void deleteListWithCycle(ListNode *head) {
    ListNode *slow = head;
    ListNode *fast = head;
    bool hasCycle = false;

    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            hasCycle = true;
            break;
        }
    }

    if (hasCycle) {
        slow = head;
        while (slow != fast) {
            slow = slow->next;
            fast = fast->next;
        }
        ListNode *prev = fast;
        while (prev->next != fast) {
            prev = prev->next;
        }
        prev->next = nullptr;
    }

    while (head != nullptr) {
        ListNode *temp = head;
        head = head->next;
        delete temp;
    }
}

int main() {
    Solution2 solution;

    /* Example 1: cycle starts at index 1 (value 2) */
    ListNode *head1 = buildListWithCycle({1, 2, 3, 4, 5}, 1);

    cout << "List (with cycle): ";
    printList(head1);

    ListNode *start1 = solution.findStartingPoint(head1);
    cout << "Cycle starts at: " << (start1 ? to_string(start1->data) : "null") << endl;

    deleteListWithCycle(head1);

    /* Example 2: no cycle */
    ListNode *head2 = buildListWithCycle({1, 3, 7, 4}, -1);

    cout << "\nList (no cycle): ";
    printList(head2);

    ListNode *start2 = solution.findStartingPoint(head2);
    cout << "Cycle starts at: " << (start2 ? to_string(start2->data) : "null") << endl;

    deleteListWithCycle(head2);

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

class ListNode {
  public:
    int data;
    ListNode *next;

    ListNode() : data(0), next(nullptr) {}

    ListNode(int x) : data(x), next(nullptr) {}

    ListNode(int x, ListNode *nextNode) : data(x), next(nextNode) {}
};

class Solution {
  public:
    /* Brute Force Approach (Copy to Array):
       Copy all node values into an array, then use two pointers
       from both ends moving inward to check for a palindrome. */
    bool isPalindrome(ListNode *head) {
        ListNode *current = head;
        vector<int> arr;

        /* Step 1: Collect all node values into an array */
        while (current != nullptr) {
            arr.push_back(current->data);
            current = current->next;
        }

        /* Step 2: Compare from both ends moving inward.
           If any mismatch is found, it's not a palindrome. */
        int list_length = arr.size();
        for (int i = 0, j = list_length - 1; i <= j; i++, j--) {
            if (arr[i] != arr[j]) {
                return false;
            }
        }
        return true;
    }

    /*
    Complexity Analysis

    Time Complexity: O(2N) — one pass to copy values, one pass to compare.
    Space Complexity: O(N) — extra array to store all node values.
    */
};

class Solution2 {
  public:
    /* Optimized Approach (Reverse Second Half):
       1. Find the middle node using slow/fast pointers.
       2. Reverse the second half of the list.
       3. Compare the first half with the reversed second half.
       4. Restore the list by re-reversing the second half. */
    bool isPalindrome(ListNode *head) {
        /* Step 1: Find the middle node */
        ListNode *mid = findMiddle(head);

        /* Step 2: Reverse the second half starting from mid */
        ListNode *secondHalf = reverseList(mid);

        /* Step 3: Compare first half and reversed second half.
           The shorter half (secondHalf for odd-length) controls termination. */
        ListNode *firstHalf = head;
        ListNode *secondHalfHead = secondHalf; // save for restoration
        bool result = true;

        while (firstHalf != nullptr && secondHalf != nullptr) {
            if (firstHalf->data != secondHalf->data) {
                result = false;
                break;
            }
            firstHalf = firstHalf->next;
            secondHalf = secondHalf->next;
        }

        /* Step 4: Restore the list by re-reversing the second half.
           Without this, the original list remains broken after the call. */
        reverseList(secondHalfHead);

        return result;
    }

    /* Helper: find the middle node using slow & fast pointers */
    ListNode *findMiddle(ListNode *head) {
        ListNode *slow = head;
        ListNode *fast = head;

        while (fast != nullptr && fast->next != nullptr) {
            slow = slow->next;
            fast = fast->next->next;
        }

        return slow;
    }

    /* Helper: iterative in-place reversal */
    ListNode *reverseList(ListNode *head) {
        ListNode *current = head;
        ListNode *prev = nullptr;
        ListNode *front = nullptr;

        while (current != nullptr) {
            front = current->next;
            current->next = prev;
            prev = current;
            current = front;
        }

        return prev;
    }

    /*
    Complexity Analysis

    Time Complexity: O(2N) — find middle (N/2) + reverse (N/2) + compare (N/2) + restore (N/2).
    Space Complexity: O(1) — only pointers used, no extra data structures.
    */
};

/* Helper: build a linked list from a vector of values */
ListNode *buildList(const vector<int> &values) {
    if (values.empty()) {
        return nullptr;
    }

    ListNode *head = new ListNode(values[0]);
    ListNode *tail = head;

    for (int i = 1; i < (int)values.size(); i++) {
        tail->next = new ListNode(values[i]);
        tail = tail->next;
    }

    return head;
}

/* Helper: print the linked list in "a -> b -> c" format */
void printList(ListNode *head) {
    ListNode *current = head;
    while (current != nullptr) {
        cout << current->data;
        if (current->next != nullptr) {
            cout << " -> ";
        }
        current = current->next;
    }
    cout << endl;
}

/* Helper: free all nodes in the linked list */
void deleteList(ListNode *&head) {
    while (head != nullptr) {
        ListNode *temp = head;
        head = head->next;
        delete temp;
    }
}

int main() {
    Solution solution;

    /* Example 1: palindrome */
    vector<int> input1 = {3, 7, 5, 7, 3};

    ListNode *head1 = buildList(input1);

    cout << "List: ";
    printList(head1);

    cout << "Is palindrome: " << (solution.isPalindrome(head1) ? "true" : "false") << endl;

    deleteList(head1);

    /* Example 2: not a palindrome */
    vector<int> input2 = {1, 1, 2, 1};

    ListNode *head2 = buildList(input2);

    cout << "\nList: ";
    printList(head2);

    cout << "Is palindrome: " << (solution.isPalindrome(head2) ? "true" : "false") << endl;

    deleteList(head2);

    return 0;
}

