    Node(int value) : data(value), left(nullptr), right(nullptr) {}
};

bool isBalancedBinaryTree(Node *root);
int height(Node *root);

int main() {
    Node *root = new Node(5);
    root->left = new Node(3);
    root->right = new Node(7);
    root->left->left = new Node(2);
    root->left->right = new Node(4);
    root->right->left = new Node(6);
    root->right->right = new Node(10);

    if (isBalancedBinaryTree(root)) {
        cout << "Balanced Tree" << endl;
    } else {
        cout << "Unbalanced Tree" << endl;
    }

    return 0;
}

/*
Complexity Analysis

Time Complexity: O(N) where N is the number of nodes in the Binary Tree. This complexity arises from visiting each node
exactly once during the postorder traversal.

Space Complexity : O(1) as no additional space or data structures is created that is proportional to the input size of
the tree. O(H) Recursive Stack Auxiliary Space : The recursion stack space is determined by the maximum depth of the
recursion, which is the height of the binary tree denoted as H. In the balanced case it is log2N and in the worst case
its N.
*/
bool isBalancedBinaryTree(Node *root) { return height(root) != -1; }

int height(Node *root) {
    if (root == nullptr) {
        return 0;
    }

    int left_height = height(root->left);
    if (left_height == -1) {
        return -1;
    }

    int right_height = height(root->right);
    if (right_height == -1) {
        return -1;
    }

    if (abs(left_height - right_height) > 1)
        return -1;

    return max(left_height, right_height) + 1;
}

#include <iostream>
#include <map>
#include <queue>

using namespace std;

struct Node {
    int data;
    Node *left;
    Node *right;

    Node(int value) : data(value), left(nullptr), right(nullptr) {}
};

vector<int> bottomView(Node *root);

int main() {
    Node *root = new Node(5);
    root->left = new Node(3);
    root->right = new Node(7);
    root->left->left = new Node(2);
    root->left->right = new Node(4);
    root->right->left = new Node(6);
    root->right->right = new Node(10);

    vector<int> bottom_view = bottomView(root);

    for (auto p : bottom_view) {
        cout << p << " ";
    }
    cout << endl;

    return 0;
}

/*
Complexity Analysis

Time Complexity: O(N) where N is the number of nodes in the Binary Tree. This complexity arises from visiting each node
exactly once during the BFS traversal.

Space Complexity: O(N) where N represents the number of nodes in the Binary Tree.
*/
vector<int> bottomView(Node *root) {
    vector<int> result;
    if (root == nullptr) {
        return result;
    }

    /* Map to store the bottom view nodes based on their vertical positions */
    map<int, int> mpp;

    /* Queue for BFS traversal, each element is a pair containing node and its vertical position */
    queue<pair<Node *, int>> q;
    q.push({root, 0});
    while (!q.empty()) {
        auto it = q.front();
        q.pop();
        Node *node = it.first;
        int vertical = it.second;

        mpp[vertical] = node->data;

        if (node->left) {
            q.push({node->left, vertical - 1});
        }

        if (node->right) {
            q.push({node->right, vertical + 1});
        }
    }

    for (auto it : mpp) {
        result.push_back(it.second);
    }

    return result;
}

#include <iostream>
#include <vector>

using namespace std;

struct Node {
    int data;
    Node *left;
    Node *right;

    Node(int value) {
        data = value;
        left = nullptr;
        right = nullptr;
    }
};

vector<int> boundaryTraversal(Node *root);
void addLeftBoundary(Node *root, vector<int> &ans);
void addRightBoundary(Node *root, vector<int> &ans);
void addLeaves(Node *root, vector<int> &ans);
bool isLeaf(Node *root);

int main() {
    // Creating the Binary Tree
    Node *root = new Node(5);
    root->left = new Node(3);
    root->right = new Node(7);
    root->left->left = new Node(2);
    root->left->right = new Node(4);
    root->right->left = new Node(6);
    root->right->right = new Node(10);

    vector<int> result = boundaryTraversal(root);
    std::cout << "Boundary Traversal of a Binary Tree: " << std::endl;
    for (int val : result) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    return 0;
}

vector<int> boundaryTraversal(Node *root) {
    vector<int> ans;
    if (root == nullptr) {
        return ans;
    }
    if (!isLeaf(root)) {
        ans.push_back(root->data);
    }

    addLeftBoundary(root, ans);
    addLeaves(root, ans);
    addRightBoundary(root, ans);

    return ans;
}

bool isLeaf(Node *root) {
    if (root->left == nullptr && root->right == nullptr) {
        return true;
    }

    return false;
}

void addLeftBoundary(Node *root, vector<int> &ans) {
    Node *current_node = root->left;
    while (current_node) {
        if (!isLeaf(current_node)) {
            ans.push_back(current_node->data);
        }
        if (current_node->left != nullptr) {
            current_node = current_node->left;
        } else {
            current_node = current_node->right;
        }
    }
}

void addRightBoundary(Node *root, vector<int> &ans) {
    Node *current_node = root->right;
    vector<int> right_boundary;
    while (current_node) {
        if (!isLeaf(current_node)) {
            right_boundary.push_back(current_node->data);
        }
        if (current_node->right != nullptr) {
            current_node = current_node->right;
        } else {
            current_node = current_node->left;
        }
    }

    for (int i = right_boundary.size() - 1; i >= 0; i--) {
        ans.push_back(right_boundary[i]);
    }
}

void addLeaves(Node *root, vector<int> &ans) {
    if (isLeaf(root)) {
        ans.push_back(root->data);
        return;
    }
    if (root->left) {
        addLeaves(root->left, ans);
    }
    if (root->right) {
        addLeaves(root->right, ans);
    }
}

#include <iostream>

using namespace std;

// TreeNode structure
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;

    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
  public:
    // Function to change the values of the nodes
    // based on the sum of its children's values.
    void changeTree(TreeNode *root) {
        // Base case: If the current node
        // is NULL, return and do nothing.
        if (root == NULL) {
            return;
        }

        // Calculate the sum of the values of
        // the left and right children, if they exist.
        int child = 0;
        if (root->left) {
            child += root->left->val;
        }
        if (root->right) {
            child += root->right->val;
        }

        // Compare the sum of children with
        // the current node's value and update
        if (child >= root->val) {
            root->val = child;
        } else {
            // If the sum is smaller, update the
            // child with the current node's value.
            if (root->left) {
                root->left->val = root->val;
            } else if (root->right) {
                root->right->val = root->val;
            }
        }

        // Recursively call the function
        // on the left and right children.
        changeTree(root->left);
        changeTree(root->right);

        // Calculate the total sum of the
        // values of the left and right
        // children, if they exist.
        int tot = 0;
        if (root->left) {
            tot += root->left->val;
        }
        if (root->right) {
            tot += root->right->val;
        }

        // If either left or right child
        // exists, update the current node's
        // value with the total sum.
        if (root->left or root->right) {
            root->val = tot;
        }
    }
};

// Function to print the inorder
// traversal of the tree
void inorderTraversal(TreeNode *root) {
    if (root == nullptr) {
        return;
    }
    inorderTraversal(root->left);
    cout << root->val << " ";
    inorderTraversal(root->right);
}

int main() {
    // Create the binary tree
    TreeNode *root = new TreeNode(3);
    root->left = new TreeNode(5);
    root->right = new TreeNode(1);
    root->left->left = new TreeNode(6);
    root->left->right = new TreeNode(2);
    root->right->left = new TreeNode(0);
    root->right->right = new TreeNode(8);
    root->left->right->left = new TreeNode(7);
    root->left->right->right = new TreeNode(4);

    Solution sol;

    // Print the inorder traversal
    // of tree before modification
    cout << "Binary Tree before modification: ";
    inorderTraversal(root);
    cout << endl;

    // Call the changeTree function
    // to modify the binary tree
    sol.changeTree(root);

    // Print the inorder traversal
    // after modification
    cout << "Binary Tree after Children Sum Property: ";
    inorderTraversal(root);
    cout << endl;

    return 0;
}

/*
Complexity Analysis

Time Complexity: O(N) where N is the number of nodes in the binary tree. This is because the algorithm traverses each
node exactly once, performing constant-time operations at each node.

Space Complexity: O(N) where N is the number of nodes in the Binary Tree.

In the worst case scenario the tree is skewed and the auxiliary recursion stack space would be stacked up to the maximum
height of the tree, resulting in a space complexity of O(N). In the optimal case of a balanced tree, the auxiliary space
would take up space proportional to O(log2N).
*/

#include <iostream>
#include <map>

using namespace std;

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;

    TreeNode(int value) : val(value), left(nullptr), right(nullptr) {}
};

TreeNode *buildTree(vector<int> &inorder, vector<int> &postorder);
TreeNode *buildTree(vector<int> &postorder, int postStart, int postEnd, vector<int> &inorder, int inStart, int inEnd,
                    map<int, int> &inMap);

/* Function to print the inorder traversal of a tree */
void printInorder(TreeNode *root) {
    if (!root) {
        return;
    }
    printInorder(root->left);
    cout << root->val << " ";
    printInorder(root->right);
}

// Function to print the given vector
void printVector(vector<int> &vec) {
    for (int i = 0; i < vec.size(); i++) {
        cout << vec[i] << " ";
    }
    cout << endl;
}

int main() {
    // Example input vectors
    vector<int> inorder = {40, 20, 50, 10, 60, 30};
    vector<int> postorder = {40, 50, 20, 60, 30, 10};

    // Display the input vectors
    cout << "Inorder Vector: ";
    printVector(inorder);

    cout << "Postorder Vector: ";
    printVector(postorder);

    // Build the binary tree and
    // print its inorder traversal
    TreeNode *root = buildTree(inorder, postorder);

    cout << "Inorder of Unique Binary Tree Created: " << endl;
    printInorder(root);
    cout << endl;

    return 0;
}

/*
Complexity Analysis

Time Complexity: O(N) where N is the number of nodes in the Binary Tree. This is because each node is processed and
visited exactly once.

The algorithm processes each element in the inorder traversal and for each element it performs constant-time operations
(lookup in the hashmap, recursive calls and variable operations). Space Complexity: O(N + log2N) where N is the number
of elements in the iwhere N is the number of nodes in the Binary Tree.

This complexity arises from the space used by the recursion stack during the recursive calls. In the worst case, the
maximum depth of the recursion stack would be equal to the height of the Binary Tree and in the optimal case the
recursion stack complexity would be O(log2N).
*/
TreeNode *buildTree(vector<int> &inorder, vector<int> &postorder) {
    map<int, int> inMap;
    int i{0};
    for (const int it : inorder) {
        inMap[it] = i++;
    }

    TreeNode *root = buildTree(postorder, 0, postorder.size() - 1, inorder, 0, inorder.size() - 1, inMap);
    return root;
}

TreeNode *buildTree(vector<int> &postorder, int postStart, int postEnd, vector<int> &inorder, int inStart, int inEnd,
                    map<int, int> &inMap) {
    if (postStart > postEnd || inStart > inEnd) {
        return nullptr;
    }

    TreeNode *root = new TreeNode(postorder[postEnd]);

    int inRoot = inMap[root->val];
    int numsLeft = inRoot - inStart;

    root->left = buildTree(postorder, postStart, postStart + numsLeft - 1, inorder, inStart, inRoot - 1, inMap);
    root->right = buildTree(postorder, postStart + numsLeft, postEnd - 1, inorder, inRoot + 1, inEnd, inMap);

    return root;
}

