/*
Complexity Analysis

Time Complexity: O(N) where N is the number of nodes in the Binary Tree. This is because each node of the Binary Tree is
visited once.

Space Complexity: O(N) where N is the number of nodes in the Binary Tree. The inorder hashmap to store the inorder array
for fast lookup takes up space proportional to the input nodes. An auxiliary stack space ~ O(H) where H is the height of
the Binary Tree is used. This is the stack space used to build the tree recursively. In the case of a skewed tree, the
height of the tree will be H ~ N hence the worst case auxiliary space is O(N).
*/
TreeNode *buildTree(vector<int> &preorder, vector<int> &inorder) {
    map<int, int> inMap;
    int i{0};
    for (const int it : inorder) {
        inMap[it] = i++;
    }

    TreeNode *root = buildTree(preorder, 0, preorder.size() - 1, inorder, 0, inorder.size() - 1, inMap);
    return root;
}

TreeNode *buildTree(vector<int> &preorder, int preStart, int preEnd, vector<int> &inorder, int inStart, int inEnd,
                    map<int, int> &inMap) {
    if (preStart > preEnd || inStart > inEnd) {
        return nullptr;
    }

    TreeNode *root = new TreeNode(preorder[preStart]);

    int inRoot = inMap[root->val];
    int numsLeft = inRoot - inStart;

    root->left = buildTree(preorder, preStart + 1, preStart + numsLeft, inorder, inStart, inRoot - 1, inMap);
    root->right = buildTree(preorder, preStart + numsLeft + 1, preEnd, inorder, inRoot + 1, inEnd, inMap);

    return root;
}

