// Function to find the height of Binary Tree
int findHeight(Node *node, int &diameter) {
    if (node == nullptr) {
        return 0;
    }

    // Recursively find the height of left and right subtrees
    int leftHeight = findHeight(node->left, diameter);
    int rightHeight = findHeight(node->right, diameter);

    diameter = max(diameter, leftHeight + rightHeight);

    // Return the maximum of heights of left and right subtrees, plus 1 for the current node
    return 1 + max(leftHeight, rightHeight);
}

int findDiameter(Node *node) {
    if (node == nullptr) {
        return 0;
    }

    int diameter{0};

    findHeight(node, diameter);

    return diameter;
}

