using namespace std;

// TreeNode structure
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;

    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
  public:
    // Initialize a global variable
    // 'prev' to keep track of the
    // previously processed node.
    TreeNode *prev = NULL;

    /* Brute Force */
    /*
    Complexity Analysis

    Time Complexity: O(N) where N is the number of nodes in the Binary Tree. Each node of the binary node is visited
    exactly once. At each node, constant-time operations are performed. Hence the time complexity is O(N).

    Space Complexity : O(log2N)where N is the number of nodes in the Binary Tree. There are no additional data
    structures or space used but the auxiliary stack space is used during recursion. Since the recursion depth can be at
    most equal to the height to the Binary Tree, the space complexity is O(H) where H is the height of the Binary Tree.
    In the ideal case, H = log2N and in the worst case H = N (skewed tree).
    */
    // void flatten(TreeNode *root) {
    //     if (root == nullptr) {
    //         return;
    //     }

    //     flatten(root->right);
    //     flatten(root->left);

    //     root->right = prev;
    //     root->left = nullptr;

    //     prev = root;
    // }

    /* Better Approach */
    /*
    Time Complexity: O(N) where N is the number of nodes in the Binary Tree. Each node of the binary node is visited
    exactly once. At each node, constant-time operations are performed. Hence the time complexity is O(N).

    Space Complexity : O(log2N) where N is the number of nodes in the Binary Tree. There are no additional data
    structures or space used but the auxiliary stack space is used during recursion. Since the recursion depth can be at
    most equal to the height to the Binary Tree, the space complexity is O(H) where H is the height of the Binary Tree.
    In the ideal case, H = log2N and in the worst case H = N (skewed tree).
    */
    // void flatten(TreeNode *root) {
    //     if (root == nullptr) {
    //         return;
    //     }

    //     stack<TreeNode *> st;
    //     st.push(root);
    //     while (!st.empty()) {
    //         TreeNode *curr = st.top();
    //         st.pop();

    //         if (curr->right) {
    //             st.push(curr->right);
    //         }

    //         if (curr->left) {
    //             st.push(curr->left);
    //         }

    //         if (!st.empty()) {
    //             curr->right = st.top();
    //         }

    //         curr->left = nullptr;
    //     }
    // }

    /* Optimal Solution */
    /*
    Time Complexity: O(2N) where N is the number of nodes in the Binary Tree.

    The time complexity is linear, as each node is visited at most twice (once for establishing the temporary link and
    once for reverting it). In each step, we perform constant-time operations, such as moving to the left or right child
    and updating pointers. Space Complexity: O(1) The space complexity is constant, as the algorithm uses only a
    constant amount of extra space irrespective of the input size.

    Morris Traversal does not use any additional data structures like stacks or recursion, making it an in-place
    algorithm. The only space utilised is for a few auxiliary variables, such as pointers to current and in-order
    predecessor nodes.
    */
    void flatten(TreeNode *root) {
        if (root == nullptr) {
            return;
        }

        TreeNode *curr = root;
        while (curr != nullptr) {
            if (curr->left != nullptr) {
                TreeNode *prev = curr->left;

                while (prev->right != nullptr) {
                    prev = prev->right;
                }

                prev->right = curr->right;
                curr->right = curr->left;
                curr->left = nullptr;
            }
            curr = curr->right;
        }
    }
};

