};

int maxWidth(Node *root);

int main() {
    Node *root = new Node(5);
    root->left = new Node(3);
    root->right = new Node(7);
    root->left->left = new Node(2);
    root->left->right = new Node(4);
    root->right->left = new Node(6);
    root->right->right = new Node(10);

    cout << "Max width of binary tree : " << maxWidth(root) << endl;

    return 0;
}

/*
Complexity Analysis

Time Complexity: O(N) - since we are doing Level Order traversal
Space Complexity: O(N) - since we are using queue data structure
*/
int maxWidth(Node *root) {
    if (!root) {
        return 0;
    }

    queue<pair<Node *, int>> q;
    q.push({root, 0});

    int max_width = 0;
    while (!q.empty()) {
        int min_ind = q.front().second;
        int size = q.size();
        int first{0};
        int last{0};
        for (int i = 0; i < size; i++) {
            int curr_id = q.front().second - min_ind;
            Node *node = q.front().first;
            q.pop();

            if (i == 0) {
                first = curr_id;
            }
            if (i == size - 1) {
                last = curr_id;
            }

            if (node->left) {
                q.push({node->left, curr_id * 2 + 1});
            }

            if (node->right) {
                q.push({node->right, curr_id * 2 + 2});
            }
        }

        max_width = max(max_width, last - first + 1);
    }

    return max_width;
}

