int timeToBurnTree(Node *root, int start) {
    map<Node *, Node *> parent_track;

    Node *start_node = markParents(root, parent_track, start);

    return findMaxDistance(parent_track, start_node);
}

Node *markParents(Node *root, map<Node *, Node *> &parent_track, int start) {
    Node *start_node;
    queue<Node *> q;
    q.push(root);
    while (!q.empty()) {
        Node *curr_node = q.front();
        if (curr_node->data == start) {
            start_node = curr_node;
        }
        q.pop();

        if (curr_node->left) {
            parent_track[curr_node->left] = curr_node;
            q.push(curr_node->left);
        }

        if (curr_node->right) {
            parent_track[curr_node->right] = curr_node;
            q.push(curr_node->right);
        }
    }

    return start_node;
}

/*
Complexity Analysis

Time Complexity: O(N) + O(N) =~ O(N), tarversing the tree twice.
Space Complexity: O(N) + O(N) + O(N) + O(N) =~ O(N), 2 queues, 2 maps.
*/
int findMaxDistance(map<Node *, Node *> &parent_track, Node *start_node) {
    int max_distance{0};
    if (start_node == nullptr) {
        return -1;
    }

    map<Node *, bool> visited_map;
    queue<Node *> q;
    q.push(start_node);
    visited_map[start_node] = true;

    while (!q.empty()) {
        int size = q.size();
        int flag{0};
        for (int i = 0; i < size; i++) {
            Node *node = q.front();
            q.pop();

            if (node->left && !visited_map[node->left]) {
                flag = 1;
                q.push(node->left);
                visited_map[node->left] = true;
            }

            if (node->right && !visited_map[node->right]) {
                flag = 1;
                q.push(node->right);
                visited_map[node->right] = true;
            }

            if (parent_track[node] && !visited_map[parent_track[node]]) {
                flag = 1;
                q.push(parent_track[node]);
                visited_map[parent_track[node]] = true;
            }
        }
        if (flag) {
            max_distance++;
        }
    }

    return max_distance;
}

#include <iostream>
#include <vector>

using namespace std;

// TreeNode structure
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;

    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
  public:
    // Function to perform iterative Morris
    // inorder traversal of a binary tree
    vector<int> getInorder(TreeNode *root) {
        // Vector to store the
        // inorder traversal result
        vector<int> inorder;
        // Pointer to the current node,
        // starting from the root
        TreeNode *cur = root;

        // Loop until the current
        // node is not NULL
        while (cur != NULL) {
            // If the current node's
            // left child is NULL
            if (cur->left == NULL) {
                // Add the value of the current
                // node to the inorder vector
                inorder.push_back(cur->val);
                // Move to the right child
                cur = cur->right;
            } else {
                // If the left child is not NULL,
                // find the predecessor (rightmost node
                // in the left subtree)
                TreeNode *prev = cur->left;
                while (prev->right && prev->right != cur) {
                    prev = prev->right;
                }

                // If the predecessor's right child
                // is NULL, establish a temporary link
                // and move to the left child
                if (prev->right == NULL) {
                    prev->right = cur;
                    cur = cur->left;
                } else {
                    // If the predecessor's right child
                    // is already linked, remove the link,
                    // add current node to inorder vector,
                    // and move to the right child
                    prev->right = NULL;
                    inorder.push_back(cur->val);
                    cur = cur->right;
                }
            }
        }

        // Return the inorder
        // traversal result
        return inorder;
    }
};

int main() {

    TreeNode *root = new TreeNode(1);
    root->left = new TreeNode(2);
    root->right = new TreeNode(3);
    root->left->left = new TreeNode(4);
    root->left->right = new TreeNode(5);
    root->left->right->right = new TreeNode(6);

    Solution sol;

    vector<int> inorder = sol.getInorder(root);

    cout << "Binary Tree Morris Inorder Traversal: ";
    for (int i = 0; i < inorder.size(); i++) {
        cout << inorder[i] << " ";
    }
    cout << endl;

    return 0;
}

/*
Complexity Analysis

Time Complexity: O(2N) where N is the number of nodes in the Binary Tree.

The time complexity is linear, as each node is visited at most twice (once for establishing the temporary link and once
for reverting it). In each step, we perform constant-time operations, such as moving to the left or right child and
updating pointers. Space Complexity: O(1) The space complexity is constant, as the algorithm uses only a constant amount
of extra space irrespective of the input size.

Morris Traversal does not use any additional data structures like stacks or recursion, making it an in-place algorithm.
The only space utilised is for a few auxiliary variables, such as pointers to current and in-order predecessor nodes.
*/

#include <iostream>
#include <vector>

using namespace std;

// TreeNode structure
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;

    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
  public:
    // Function to perform iterative Morris
    // preorder traversal of a binary tree
    vector<int> getPreorder(TreeNode *root) {
        // Vector to store the
        // preorder traversal result
        vector<int> preorder;

        // Pointer to the current node,
        // starting with the root
        TreeNode *cur = root;

        // Iterate until the
        // current node becomes NULL
        while (cur != NULL) {
            // If the current node
            // has no left child
            if (cur->left == NULL) {
                // Add the value of the
                // current node to the preorder vector
                preorder.push_back(cur->val);

                // Move to the right child
                cur = cur->right;
            } else {
                // If the current node has a left child
                // Create a pointer to traverse to the
                // rightmost node in the left subtree
                TreeNode *prev = cur->left;

                // Traverse to the rightmost node in the
                // left subtree or until we find a node
                // whose right child is not yet processed
                while (prev->right && prev->right != cur) {
                    prev = prev->right;
                }

                // If the right child of the
                // rightmost node is NULL
                if (prev->right == NULL) {
                    // Set the right child of the
                    // rightmost node to the current node
                    prev->right = cur;

                    // Add the value of the
                    // current node to the preorder vector
                    preorder.push_back(cur->val);

                    // Move to the left child
                    cur = cur->left;
                } else {
                    // If the right child of the
                    // rightmost node is not NULL
                    // Reset the right child to NULL
                    prev->right = NULL;

                    // Move to the right child
                    cur = cur->right;
                }
            }
        }

        // Return the resulting
        // preorder traversal vector
        return preorder;
    }
};

int main() {

    TreeNode *root = new TreeNode(1);
    root->left = new TreeNode(2);
    root->right = new TreeNode(3);
    root->left->left = new TreeNode(4);
    root->left->right = new TreeNode(5);
    root->left->right->right = new TreeNode(6);

    Solution sol;

    vector<int> preorder = sol.getPreorder(root);

    cout << "Binary Tree Morris Preorder Traveral: ";
    for (int i = 0; i < preorder.size(); i++) {
        cout << preorder[i] << " ";
    }
    cout << endl;

    return 0;
}

/*
Complexity Analysis

Time Complexity: O(2N) where N is the number of nodes in the Binary Tree.

The time complexity is linear, as each node is visited at most twice (once for establishing the temporary link and once
for reverting it). In each step, we perform constant-time operations, such as moving to the left or right child and
updating pointers. Space Complexity: O(1) The space complexity is constant, as the algorithm uses only a constant amount
of extra space irrespective of the input size.

Morris Traversal does not use any additional data structures like stacks or recursion, making it an in-place algorithm.
The only space utilised is for a few auxiliary variables, such as pointers to current and in-order predecessor nodes.
*/

#include <iostream>
#include <queue>
#include <unordered_map>

using namespace std;

struct Node {
    int data;
    Node *left;
    Node *right;

    Node(int value) : data(value), left(nullptr), right(nullptr) {}
};

void markParents(Node *root, unordered_map<Node *, Node *> &parent_track, Node *target);
vector<int> distanceK(Node *root, Node *target, int k);

int main() {
    Node *root = new Node(3);
    root->left = new Node(5);
    root->right = new Node(1);
    root->left->left = new Node(6);
    root->left->right = new Node(2);
    root->right->left = new Node(0);
    root->right->right = new Node(8);
    root->left->right->left = new Node(7);
    root->left->right->right = new Node(4);

    int k = 2;
    Node *target = root->left;
    vector<int> result = distanceK(root, target, k);

    cout << "The nodes at a distance of " << k << " for the node " << target->data << " is : ";
    for (const auto it : result) {
        cout << it << " ";
    }
    cout << endl;

    return 0;
}

void markParents(Node *root, unordered_map<Node *, Node *> &parent_track, Node *target) {
    queue<Node *> q;
    q.push(root);
    while (!q.empty()) {
        Node *curr_node = q.front();
        q.pop();

        if (curr_node->left) {
            parent_track[curr_node->left] = curr_node;
            q.push(curr_node->left);
        }

        if (curr_node->right) {
            parent_track[curr_node->right] = curr_node;
            q.push(curr_node->right);
        }
    }
}

/*
Complexity Analysis

Time Complexity: O(N) + O(N) =~ O(N), tarversing the tree twice.
Space Complexity: O(N) + O(N) + O(N) + O(N) =~ O(N), 2 queues, 2 maps.
*/
vector<int> distanceK(Node *root, Node *target, int k) {
    vector<int> result;
    if (root == nullptr || target == nullptr) {
        return result;
    }

    unordered_map<Node *, Node *> parent_track;
    markParents(root, parent_track, target);

    unordered_map<Node *, bool> visited_map;
    queue<Node *> q;
    q.push(target);
    visited_map[target] = true;

    int curr_level{0};
    while (!q.empty()) {
        int size = q.size();

        if (curr_level++ == k) {
            break;
        }

        for (int i = 0; i < size; i++) {
            Node *node = q.front();
            q.pop();

            if (node->left && !visited_map[node->left]) {
                q.push(node->left);
                visited_map[node->left] = true;
            }

            if (node->right && !visited_map[node->right]) {
                q.push(node->right);
                visited_map[node->right] = true;
            }

            if (parent_track[node] && !visited_map[parent_track[node]]) {
                q.push(parent_track[node]);
                visited_map[parent_track[node]] = true;
            }
        }
    }

    while (!q.empty()) {
        Node *node = q.front();
        q.pop();
        result.push_back(node->data);
    }

    return result;
}

