/*
Complexity Analysis

Time Complexity: O(N) where N is the number of nodes in the binary tree as each node of the binary tree is visited
exactly once in the inorder traversal.

Space Complexity: O(N) awhere N is the number of nodes in the binary tree. This is because the stack can potentially
hold all nodes in the tree when dealing with a skewed tree (all nodes have only one child), consuming space proportional
to the number of nodes.

O(H): In the average case or for a balanced tree, the maximum number of nodes that could be in the stack at any given
time would be roughly the height of the tree hence O(log2N).
*/
vector<int> getPath(Node *root, int target) {
    vector<int> result;
    if (root == nullptr) {
        return result;
    }

    getPathHelper(root, result, target);

    return result;
}

bool getPathHelper(Node *root, vector<int> &result, int target) {
    if (root == nullptr) {
        return false;
    }

    result.push_back(root->data);

    if (root->data == target) {
        return true;
    }

    if (getPathHelper(root->left, result, target) || getPathHelper(root->right, result, target)) {
        return true;
    }

    result.pop_back();

    return false;
}

