/*
Complexity Analysis

Time Complexity: O(N) where N is the number of nodes in the Binary Tree. This complexity arises from visiting each node
exactly once during the BFS traversal.

Space Complexity: O(H) where H represents the height of the Binary Tree.
*/
vector<int> rightView(Node *root) {
    vector<int> result;
    recursion(root, 0, result);
    return result;
}

void recursion(Node *root, int level, vector<int> &res) {
    if (root == nullptr) {
        return;
    }

    if (res.size() == level) {
        res.push_back(root->data);
    }

    if (root->right) {
        recursion(root->right, level + 1, res);
    }

    if (root->left) {
        recursion(root->left, level + 1, res);
    }
}

