};

string serialize(TreeNode *root);
TreeNode *deserialize(string serialized_str);

void inorder(TreeNode *root) {
    if (!root) {
        return;
    }
    inorder(root->left);
    cout << root->data << " ";
    inorder(root->right);
}

int main() {
    TreeNode *root = new TreeNode(1);
    root->left = new TreeNode(2);
    root->right = new TreeNode(3);
    root->right->left = new TreeNode(6);
    root->right->right = new TreeNode(7);

    cout << "Orignal Tree: ";
    inorder(root);
    cout << endl;

    string serialized = serialize(root);
    cout << "Serialized: " << serialized << endl;

    TreeNode *deserialized = deserialize(serialized);
    cout << "Tree after deserialisation: ";
    inorder(deserialized);
    cout << endl;

    return 0;
}

/*
Complexity Analysis

Time Complexity: O(N)

serialize function: O(N), where N is the number of nodes in the tree. This is because the function performs a
level-order traversal of the tree, visiting each node once. deserialize function: O(N), where N is the number of nodes
in the tree. Similar to the serialize function, it processes each node once while reconstructing the tree. Space
Complexity: O(N)

serialize function: O(N), where N is the maximum number of nodes at any level in the tree. In the worst case, the queue
can hold all nodes at the last level of the tree. deserialize function: O(N), where N is the maximum number of nodes at
any level in the tree. The queue is used to store nodes during the reconstruction process, and in the worst case, it may
hold all nodes at the last level.
*/

/* Encodes a tree to a single string. */
string serialize(TreeNode *root) {
    if (!root) {
        return "";
    }
    string serialized_str;
    queue<TreeNode *> q;
    q.push(root);
    while (!q.empty()) {
        TreeNode *curr_node = q.front();
        q.pop();

        if (curr_node == nullptr) {
            serialized_str.append("#,");
        } else {
            serialized_str.append(to_string(curr_node->data) + ",");
            q.push(curr_node->left);
            q.push(curr_node->right);
        }
    }

    return serialized_str;
}

/* Decodes your encoded data to tree. */
TreeNode *deserialize(string data) {
    if (data.size() == 0) {
        return nullptr;
    }

    stringstream s(data);
    string str;
    getline(s, str, ',');
    TreeNode *root = new TreeNode(stoi(str));
    queue<TreeNode *> q;
    q.push(root);
    while (!q.empty()) {
        TreeNode *curr_node = q.front();
        q.pop();

        getline(s, str, ',');

        if (str == "#") {
            curr_node->left = nullptr;
        } else {
            TreeNode *leftNode = new TreeNode(stoi(str));
            curr_node->left = leftNode;
            q.push(leftNode);
        }

        getline(s, str, ',');
        if (str == "#") {
            curr_node->right = nullptr;
        } else {
            TreeNode *rightNode = new TreeNode(stoi(str));
            curr_node->right = rightNode;
            q.push(rightNode);
        }
    }

    return root;
}

