/*
Complexity Analysis

Time Complexity: O(N) where N is the number of nodes in the Binary Tree. This complexity arises from visiting each node
exactly once during the BFS traversal.

Space Complexity: O(N) where N represents the number of nodes in the Binary Tree.
*/
vector<int> topView(Node *root) {
    vector<int> result;
    if (root == nullptr) {
        return result;
    }
    map<int, int> mpp;
    queue<pair<Node *, int>> q;
    q.push({root, 0});
    while (!q.empty()) {
        auto it = q.front();
        q.pop();
        Node *node = it.first;
        int vertical = it.second;

        if (mpp.find(vertical) == mpp.end()) {
            mpp[vertical] = node->data;
        }

        if (node->left) {
            q.push({node->left, vertical - 1});
        }

        if (node->right) {
            q.push({node->right, vertical + 1});
        }
    }

    for (auto it : mpp) {
        result.push_back(it.second);
    }

    return result;
}

