    root->right->left = new Node(6);
    root->right->right = new Node(10);

    vector<vector<int>> vertical_order_traversal = verticalOrderTraversal(root);

    std::cout << "Vertical Traversal of a Binary Tree: " << std::endl;
    for (auto col : vertical_order_traversal) {
        for (auto val : col) {
            std::cout << val << " ";
        }
    }
    std::cout << std::endl;

    return 0;
}

/*
Complexity Analysis :

Time Complexity : O(N) logN
Space Complexity : O(N)
*/
vector<vector<int>> verticalOrderTraversal(Node *root) {
    vector<vector<int>> result;
    if (root == nullptr) {
        return result;
    }

    /* queue<pair<Node*, pair<vertical, level> */
    queue<pair<Node *, pair<int, int>>> nodeQueue;
    nodeQueue.push({root, {0, 0}});
    /* map<vertical, map<level, multiset<int> > > */
    map<int, map<int, multiset<int>>> bufferedNodes;
    while (!nodeQueue.empty()) {
        auto p = nodeQueue.front();
        nodeQueue.pop();

        Node *current_node = p.first;
        int x = p.second.first;
        int y = p.second.second;

        bufferedNodes[x][y].insert(current_node->data);

        if (current_node->left) {
            nodeQueue.push({current_node->left, {x - 1, y + 1}});
        }
        if (current_node->right) {
            nodeQueue.push({current_node->right, {x + 1, y + 1}});
        }
    }

    for (auto p : bufferedNodes) {
        vector<int> col;
        for (auto q : p.second) {
            col.insert(col.end(), q.second.begin(), q.second.end());
        }
        result.push_back(col);
    }

    return result;
}

